static int xan_unpack(uint8_t *dest, const int dest_len,

                      const uint8_t *src, const int src_len)

{

    uint8_t opcode;

    int size;

    uint8_t *orig_dest = dest;

    const uint8_t *src_end = src + src_len;

    const uint8_t *dest_end = dest + dest_len;



    while (dest < dest_end) {

        opcode = *src++;



        if (opcode < 0xe0) {

            int size2, back;

            if ((opcode & 0x80) == 0) {

                size  = opcode & 3;

                back  = ((opcode & 0x60) << 3) + *src++ + 1;

                size2 = ((opcode & 0x1c) >> 2) + 3;

            } else if ((opcode & 0x40) == 0) {

                size  = *src >> 6;

                back  = (bytestream_get_be16(&src) & 0x3fff) + 1;

                size2 = (opcode & 0x3f) + 4;

            } else {

                size  = opcode & 3;

                back  = ((opcode & 0x10) << 12) + bytestream_get_be16(&src) + 1;

                size2 = ((opcode & 0x0c) <<  6) + *src++ + 5;

                if (size + size2 > dest_end - dest)

                    break;

            }

            if (src + size > src_end || dest + size + size2 > dest_end ||

                dest - orig_dest + size < back)

                return -1;

            bytestream_get_buffer(&src, dest, size);

            dest += size;

            av_memcpy_backptr(dest, back, size2);

            dest += size2;

        } else {

            int finish = opcode >= 0xfc;



            size = finish ? opcode & 3 : ((opcode & 0x1f) << 2) + 4;

            if (src + size > src_end || dest + size > dest_end)

                return -1;

            bytestream_get_buffer(&src, dest, size);

            dest += size;

            if (finish)

                break;

        }

    }

    return dest - orig_dest;

}

void virtio_save(VirtIODevice *vdev, QEMUFile *f)

{

    BusState *qbus = qdev_get_parent_bus(DEVICE(vdev));

    VirtioBusClass *k = VIRTIO_BUS_GET_CLASS(qbus);

    VirtioDeviceClass *vdc = VIRTIO_DEVICE_GET_CLASS(vdev);

    uint32_t guest_features_lo = (vdev->guest_features & 0xffffffff);

    int i;



    if (k->save_config) {

        k->save_config(qbus->parent, f);

    }



    qemu_put_8s(f, &vdev->status);

    qemu_put_8s(f, &vdev->isr);

    qemu_put_be16s(f, &vdev->queue_sel);

    qemu_put_be32s(f, &guest_features_lo);

    qemu_put_be32(f, vdev->config_len);

    qemu_put_buffer(f, vdev->config, vdev->config_len);



    for (i = 0; i < VIRTIO_QUEUE_MAX; i++) {

        if (vdev->vq[i].vring.num == 0)

            break;

    }



    qemu_put_be32(f, i);



    for (i = 0; i < VIRTIO_QUEUE_MAX; i++) {

        if (vdev->vq[i].vring.num == 0)

            break;



        qemu_put_be32(f, vdev->vq[i].vring.num);

        if (k->has_variable_vring_alignment) {

            qemu_put_be32(f, vdev->vq[i].vring.align);

        }

        /* XXX virtio-1 devices */

        qemu_put_be64(f, vdev->vq[i].vring.desc);

        qemu_put_be16s(f, &vdev->vq[i].last_avail_idx);

        if (k->save_queue) {

            k->save_queue(qbus->parent, i, f);

        }

    }



    if (vdc->save != NULL) {

        vdc->save(vdev, f);

    }



    if (vdc->vmsd) {

        vmstate_save_state(f, vdc->vmsd, vdev, NULL);

    }



    /* Subsections */

    vmstate_save_state(f, &vmstate_virtio, vdev, NULL);

}

