void test_fcmp(double a, double b)

{

    long eflags, fpus;



    fpu_clear_exceptions();

    asm("fcom %2\n"

        "fstsw %%ax\n"

        : "=a" (fpus)

        : "t" (a), "u" (b));

    printf("fcom(%f %f)=%04lx \n",

           a, b, fpus & (0x4500 | FPUS_EMASK));

    fpu_clear_exceptions();

    asm("fucom %2\n"

        "fstsw %%ax\n"

        : "=a" (fpus)

        : "t" (a), "u" (b));

    printf("fucom(%f %f)=%04lx\n",

           a, b, fpus & (0x4500 | FPUS_EMASK));

    if (TEST_FCOMI) {

        /* test f(u)comi instruction */

        fpu_clear_exceptions();

        asm("fcomi %3, %2\n"

            "fstsw %%ax\n"

            "pushf\n"

            "pop %0\n"

            : "=r" (eflags), "=a" (fpus)

            : "t" (a), "u" (b));

        printf("fcomi(%f %f)=%04lx %02lx\n",

               a, b, fpus & FPUS_EMASK, eflags & (CC_Z | CC_P | CC_C));

        fpu_clear_exceptions();

        asm("fucomi %3, %2\n"

            "fstsw %%ax\n"

            "pushf\n"

            "pop %0\n"

            : "=r" (eflags), "=a" (fpus)

            : "t" (a), "u" (b));

        printf("fucomi(%f %f)=%04lx %02lx\n",

               a, b, fpus & FPUS_EMASK, eflags & (CC_Z | CC_P | CC_C));

    }

    fpu_clear_exceptions();

    asm volatile("fxam\n"

                 "fstsw %%ax\n"

                 : "=a" (fpus)

                 : "t" (a));

    printf("fxam(%f)=%04lx\n", a, fpus & 0x4700);

    fpu_clear_exceptions();

}

static void check_suspend_mode(GuestSuspendMode mode, Error **errp)

{

    SYSTEM_POWER_CAPABILITIES sys_pwr_caps;

    Error *local_err = NULL;



    ZeroMemory(&sys_pwr_caps, sizeof(sys_pwr_caps));

    if (!GetPwrCapabilities(&sys_pwr_caps)) {

        error_setg(&local_err, QERR_QGA_COMMAND_FAILED,

                   "failed to determine guest suspend capabilities");

        goto out;

    }



    switch (mode) {

    case GUEST_SUSPEND_MODE_DISK:

        if (!sys_pwr_caps.SystemS4) {

            error_setg(&local_err, QERR_QGA_COMMAND_FAILED,

                       "suspend-to-disk not supported by OS");

        }

        break;

    case GUEST_SUSPEND_MODE_RAM:

        if (!sys_pwr_caps.SystemS3) {

            error_setg(&local_err, QERR_QGA_COMMAND_FAILED,

                       "suspend-to-ram not supported by OS");

        }

        break;

    default:

        error_setg(&local_err, QERR_INVALID_PARAMETER_VALUE, "mode",

                   "GuestSuspendMode");

    }



out:

    if (local_err) {

        error_propagate(errp, local_err);

    }

}

static int compare_floats(const float *a, const float *b, int len,

                          float max_diff)

{

    int i;

    for (i = 0; i < len; i++) {

        if (fabsf(a[i] - b[i]) > max_diff) {

            av_log(NULL, AV_LOG_ERROR, "%d: %- .12f - %- .12f = % .12g\n",

                   i, a[i], b[i], a[i] - b[i]);

            return -1;

        }

    }

    return 0;

}

