}

static int bochs_open(BlockDriverState *bs, int flags)

{

    BDRVBochsState *s = bs->opaque;

    int i;

    struct bochs_header bochs;

    struct bochs_header_v1 header_v1;



    bs->read_only = 1; // no write support yet



    if (bdrv_pread(bs->file, 0, &bochs, sizeof(bochs)) != sizeof(bochs)) {

        goto fail;

    }



    if (strcmp(bochs.magic, HEADER_MAGIC) ||

        strcmp(bochs.type, REDOLOG_TYPE) ||

        strcmp(bochs.subtype, GROWING_TYPE) ||

	((le32_to_cpu(bochs.version) != HEADER_VERSION) &&

	(le32_to_cpu(bochs.version) != HEADER_V1))) {

        return -EMEDIUMTYPE;

    }



    if (le32_to_cpu(bochs.version) == HEADER_V1) {

      memcpy(&header_v1, &bochs, sizeof(bochs));

      bs->total_sectors = le64_to_cpu(header_v1.extra.redolog.disk) / 512;

    } else {

      bs->total_sectors = le64_to_cpu(bochs.extra.redolog.disk) / 512;

    }



    s->catalog_size = le32_to_cpu(bochs.extra.redolog.catalog);

    s->catalog_bitmap = g_malloc(s->catalog_size * 4);

    if (bdrv_pread(bs->file, le32_to_cpu(bochs.header), s->catalog_bitmap,

                   s->catalog_size * 4) != s->catalog_size * 4)

	goto fail;

    for (i = 0; i < s->catalog_size; i++)

	le32_to_cpus(&s->catalog_bitmap[i]);



    s->data_offset = le32_to_cpu(bochs.header) + (s->catalog_size * 4);



    s->bitmap_blocks = 1 + (le32_to_cpu(bochs.extra.redolog.bitmap) - 1) / 512;

    s->extent_blocks = 1 + (le32_to_cpu(bochs.extra.redolog.extent) - 1) / 512;



    s->extent_size = le32_to_cpu(bochs.extra.redolog.extent);



    qemu_co_mutex_init(&s->lock);

    return 0;

 fail:

    return -1;

}

static void rx_stop_cont_test(const QVirtioBus *bus, QVirtioDevice *dev,

                              QGuestAllocator *alloc, QVirtQueue *vq,

                              int socket)

{

    uint64_t req_addr;

    uint32_t free_head;

    char test[] = "TEST";

    char buffer[64];

    int len = htonl(sizeof(test));

    struct iovec iov[] = {

        {

            .iov_base = &len,

            .iov_len = sizeof(len),

        }, {

            .iov_base = test,

            .iov_len = sizeof(test),

        },

    };

    int ret;



    req_addr = guest_alloc(alloc, 64);



    free_head = qvirtqueue_add(vq, req_addr, 64, true, false);

    qvirtqueue_kick(bus, dev, vq, free_head);



    qmp("{ 'execute' : 'stop'}");



    ret = iov_send(socket, iov, 2, 0, sizeof(len) + sizeof(test));

    g_assert_cmpint(ret, ==, sizeof(test) + sizeof(len));



    /* We could check the status, but this command is more importantly to

     * ensure the packet data gets queued in QEMU, before we do 'cont'.

     */

    qmp("{ 'execute' : 'query-status'}");

    qmp("{ 'execute' : 'cont'}");



    qvirtio_wait_queue_isr(bus, dev, vq, QVIRTIO_NET_TIMEOUT_US);

    memread(req_addr + VNET_HDR_SIZE, buffer, sizeof(test));

    g_assert_cmpstr(buffer, ==, "TEST");



    guest_free(alloc, req_addr);

}

void ff_acelp_lspd2lpc(const double *lsp, float *lpc)

{

    double pa[6], qa[6];

    int   i;



    lsp2polyf(lsp,     pa, 5);

    lsp2polyf(lsp + 1, qa, 5);



    for (i=4; i>=0; i--)

    {

        double paf = pa[i+1] + pa[i];

        double qaf = qa[i+1] - qa[i];



        lpc[i  ] = 0.5*(paf+qaf);

        lpc[9-i] = 0.5*(paf-qaf);

    }

}

