    GString *gstr_list = g_string_new("");

    GString *gstr_union = g_string_new("");

    int i;



    for (i = 0; i < 32; i++) {

        g_string_append_printf(gstr_list, "%d", i);

        if (i != 31) {

            g_string_append(gstr_list, ", ");

