static void report_unsupported_feature(BlockDriverState *bs,

    Error **errp, Qcow2Feature *table, uint64_t mask)

{

    while (table && table->name[0] != '\0') {

        if (table->type == QCOW2_FEAT_TYPE_INCOMPATIBLE) {

            if (mask & (1 << table->bit)) {

                report_unsupported(bs, errp, "%.46s", table->name);

                mask &= ~(1 << table->bit);

            }

        }

        table++;

    }



    if (mask) {

        report_unsupported(bs, errp, "Unknown incompatible feature: %" PRIx64,

                           mask);

    }

}

static void decode_p_block(FourXContext *f, uint16_t *dst, uint16_t *src, int log2w, int log2h, int stride){

    const int index= size2index[log2h][log2w];

    const int h= 1<<log2h;

    int code= get_vlc2(&f->gb, block_type_vlc[1-(f->version>1)][index].table, BLOCK_TYPE_VLC_BITS, 1);

    uint16_t *start= (uint16_t*)f->last_picture.data[0];

    uint16_t *end= start + stride*(f->avctx->height-h+1) - (1<<log2w);



    assert(code>=0 && code<=6);



    if(code == 0){

        src += f->mv[ *f->bytestream++ ];

        if(start > src || src > end){

            av_log(f->avctx, AV_LOG_ERROR, "mv out of pic\n");

            return;

        }

        mcdc(dst, src, log2w, h, stride, 1, 0);

    }else if(code == 1){

        log2h--;

        decode_p_block(f, dst                  , src                  , log2w, log2h, stride);

        decode_p_block(f, dst + (stride<<log2h), src + (stride<<log2h), log2w, log2h, stride);

    }else if(code == 2){

        log2w--;

        decode_p_block(f, dst             , src             , log2w, log2h, stride);

        decode_p_block(f, dst + (1<<log2w), src + (1<<log2w), log2w, log2h, stride);

    }else if(code == 3 && f->version<2){

        mcdc(dst, src, log2w, h, stride, 1, 0);

    }else if(code == 4){

        src += f->mv[ *f->bytestream++ ];

        if(start > src || src > end){

            av_log(f->avctx, AV_LOG_ERROR, "mv out of pic\n");

            return;

        }

        mcdc(dst, src, log2w, h, stride, 1, av_le2ne16(*f->wordstream++));

    }else if(code == 5){

        mcdc(dst, src, log2w, h, stride, 0, av_le2ne16(*f->wordstream++));

    }else if(code == 6){

        if(log2w){

            dst[0] = av_le2ne16(*f->wordstream++);

            dst[1] = av_le2ne16(*f->wordstream++);

        }else{

            dst[0     ] = av_le2ne16(*f->wordstream++);

            dst[stride] = av_le2ne16(*f->wordstream++);

        }

    }

}

