static void usb_serial_handle_data(USBDevice *dev, USBPacket *p)

{

    USBSerialState *s = (USBSerialState *)dev;

    uint8_t devep = p->ep->nr;

    struct iovec *iov;

    uint8_t header[2];

    int i, first_len, len;



    switch (p->pid) {

    case USB_TOKEN_OUT:

        if (devep != 2)

            goto fail;

        for (i = 0; i < p->iov.niov; i++) {

            iov = p->iov.iov + i;

            qemu_chr_fe_write(s->cs, iov->iov_base, iov->iov_len);

        }

        p->actual_length = p->iov.size;

        break;



    case USB_TOKEN_IN:

        if (devep != 1)

            goto fail;

        first_len = RECV_BUF - s->recv_ptr;

        len = p->iov.size;

        if (len <= 2) {

            p->status = USB_RET_NAK;

            break;

        }

        header[0] = usb_get_modem_lines(s) | 1;

        /* We do not have the uart details */

        /* handle serial break */

        if (s->event_trigger && s->event_trigger & FTDI_BI) {

            s->event_trigger &= ~FTDI_BI;

            header[1] = FTDI_BI;

            usb_packet_copy(p, header, 2);

            break;

        } else {

            header[1] = 0;

        }

        len -= 2;

        if (len > s->recv_used)

            len = s->recv_used;

        if (!len) {

            p->status = USB_RET_NAK;

            break;

        }

        if (first_len > len)

            first_len = len;

        usb_packet_copy(p, header, 2);

        usb_packet_copy(p, s->recv_buf + s->recv_ptr, first_len);

        if (len > first_len)

            usb_packet_copy(p, s->recv_buf, len - first_len);

        s->recv_used -= len;

        s->recv_ptr = (s->recv_ptr + len) % RECV_BUF;

        break;



    default:

        DPRINTF("Bad token\n");

    fail:

        p->status = USB_RET_STALL;

        break;

    }

}

static const uint8_t *read_huffman_tables(FourXContext *f,

                                          const uint8_t * const buf, int buf_size)

{

    int frequency[512] = { 0 };

    uint8_t flag[512];

    int up[512];

    uint8_t len_tab[257];

    int bits_tab[257];

    int start, end;

    const uint8_t *ptr = buf;

    const uint8_t *ptr_end = buf + buf_size;

    int j;



    memset(up, -1, sizeof(up));



    start = *ptr++;

    end   = *ptr++;

    for (;;) {

        int i;



        if (start <= end && ptr_end - ptr < end - start + 1 + 1)

            return NULL;

        for (i = start; i <= end; i++)

            frequency[i] = *ptr++;

        start = *ptr++;

        if (start == 0)

            break;



        end = *ptr++;

    }

    frequency[256] = 1;



    while ((ptr - buf) & 3)

        ptr++; // 4byte align



    for (j = 257; j < 512; j++) {

        int min_freq[2] = { 256 * 256, 256 * 256 };

        int smallest[2] = { 0, 0 };

        int i;

        for (i = 0; i < j; i++) {

            if (frequency[i] == 0)

                continue;

            if (frequency[i] < min_freq[1]) {

                if (frequency[i] < min_freq[0]) {

                    min_freq[1] = min_freq[0];

                    smallest[1] = smallest[0];

                    min_freq[0] = frequency[i];

                    smallest[0] = i;

                } else {

                    min_freq[1] = frequency[i];

                    smallest[1] = i;

                }

            }

        }

        if (min_freq[1] == 256 * 256)

            break;



        frequency[j]           = min_freq[0] + min_freq[1];

        flag[smallest[0]]      = 0;

        flag[smallest[1]]      = 1;

        up[smallest[0]]        =

        up[smallest[1]]        = j;

        frequency[smallest[0]] = frequency[smallest[1]] = 0;

    }



    for (j = 0; j < 257; j++) {

        int node, len = 0, bits = 0;



        for (node = j; up[node] != -1; node = up[node]) {

            bits += flag[node] << len;

            len++;

            if (len > 31)

                // can this happen at all ?

                av_log(f->avctx, AV_LOG_ERROR,

                       "vlc length overflow\n");

        }



        bits_tab[j] = bits;

        len_tab[j]  = len;

    }



    if (init_vlc(&f->pre_vlc, ACDC_VLC_BITS, 257, len_tab, 1, 1,

                 bits_tab, 4, 4, 0))

        return NULL;



    return ptr;

}

static void tgen64_ori(TCGContext *s, TCGReg dest, tcg_target_ulong val)

{

    static const S390Opcode oi_insns[4] = {

        RI_OILL, RI_OILH, RI_OIHL, RI_OIHH

    };

    static const S390Opcode nif_insns[2] = {

        RIL_OILF, RIL_OIHF

    };



    int i;



    /* Look for no-op.  */

    if (val == 0) {

        return;

    }



    if (facilities & FACILITY_EXT_IMM) {

        /* Try all 32-bit insns that can perform it in one go.  */

        for (i = 0; i < 4; i++) {

            tcg_target_ulong mask = (0xffffull << i*16);

            if ((val & mask) != 0 && (val & ~mask) == 0) {

                tcg_out_insn_RI(s, oi_insns[i], dest, val >> i*16);

                return;

            }

        }



        /* Try all 48-bit insns that can perform it in one go.  */

        for (i = 0; i < 2; i++) {

            tcg_target_ulong mask = (0xffffffffull << i*32);

            if ((val & mask) != 0 && (val & ~mask) == 0) {

                tcg_out_insn_RIL(s, nif_insns[i], dest, val >> i*32);

                return;

            }

        }



        /* Perform the OR via sequential modifications to the high and

           low parts.  Do this via recursion to handle 16-bit vs 32-bit

           masks in each half.  */

        tgen64_ori(s, dest, val & 0x00000000ffffffffull);

        tgen64_ori(s, dest, val & 0xffffffff00000000ull);

    } else {

        /* With no extended-immediate facility, we don't need to be so

           clever.  Just iterate over the insns and mask in the constant.  */

        for (i = 0; i < 4; i++) {

            tcg_target_ulong mask = (0xffffull << i*16);

            if ((val & mask) != 0) {

                tcg_out_insn_RI(s, oi_insns[i], dest, val >> i*16);

            }

        }

    }

}

static int show_stream(WriterContext *w, AVFormatContext *fmt_ctx, int stream_idx, InputStream *ist, int in_program)

{

    AVStream *stream = ist->st;

    AVCodecParameters *par;

    AVCodecContext *dec_ctx;

    char val_str[128];

    const char *s;

    AVRational sar, dar;

    AVBPrint pbuf;

    const AVCodecDescriptor *cd;

    int ret = 0;

    const char *profile = NULL;



    av_bprint_init(&pbuf, 1, AV_BPRINT_SIZE_UNLIMITED);



    writer_print_section_header(w, in_program ? SECTION_ID_PROGRAM_STREAM : SECTION_ID_STREAM);



    print_int("index", stream->index);



    par     = stream->codecpar;

    dec_ctx = ist->dec_ctx;

    if (cd = avcodec_descriptor_get(par->codec_id)) {

        print_str("codec_name", cd->name);

        if (!do_bitexact) {

            print_str("codec_long_name",

                      cd->long_name ? cd->long_name : "unknown");

        }

    } else {

        print_str_opt("codec_name", "unknown");

        if (!do_bitexact) {

            print_str_opt("codec_long_name", "unknown");

        }

    }



    if (!do_bitexact && (profile = avcodec_profile_name(par->codec_id, par->profile)))

        print_str("profile", profile);

    else {

        if (par->profile != FF_PROFILE_UNKNOWN) {

            char profile_num[12];

            snprintf(profile_num, sizeof(profile_num), "%d", par->profile);

            print_str("profile", profile_num);

        } else

            print_str_opt("profile", "unknown");

    }



    s = av_get_media_type_string(par->codec_type);

    if (s) print_str    ("codec_type", s);

    else   print_str_opt("codec_type", "unknown");

#if FF_API_LAVF_AVCTX

    if (dec_ctx)

        print_q("codec_time_base", dec_ctx->time_base, '/');

#endif



    /* print AVI/FourCC tag */

    print_str("codec_tag_string",    av_fourcc2str(par->codec_tag));

    print_fmt("codec_tag", "0x%04"PRIx32, par->codec_tag);



    switch (par->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        print_int("width",        par->width);

        print_int("height",       par->height);

        if (dec_ctx) {

            print_int("coded_width",  dec_ctx->coded_width);

            print_int("coded_height", dec_ctx->coded_height);

        }

        print_int("has_b_frames", par->video_delay);

        sar = av_guess_sample_aspect_ratio(fmt_ctx, stream, NULL);

        if (sar.den) {

            print_q("sample_aspect_ratio", sar, ':');

            av_reduce(&dar.num, &dar.den,

                      par->width  * sar.num,

                      par->height * sar.den,

                      1024*1024);

            print_q("display_aspect_ratio", dar, ':');

        } else {

            print_str_opt("sample_aspect_ratio", "N/A");

            print_str_opt("display_aspect_ratio", "N/A");

        }

        s = av_get_pix_fmt_name(par->format);

        if (s) print_str    ("pix_fmt", s);

        else   print_str_opt("pix_fmt", "unknown");

        print_int("level",   par->level);

        if (par->color_range != AVCOL_RANGE_UNSPECIFIED)

            print_str    ("color_range", av_color_range_name(par->color_range));

        else

            print_str_opt("color_range", "N/A");



        if (par->color_space != AVCOL_SPC_UNSPECIFIED)

            print_str("color_space", av_color_space_name(par->color_space));

        else

            print_str_opt("color_space", av_color_space_name(par->color_space));



        if (par->color_trc != AVCOL_TRC_UNSPECIFIED)

