static void pci_ivshmem_exit(PCIDevice *dev)

{

    IVShmemState *s = IVSHMEM(dev);

    int i;



    fifo8_destroy(&s->incoming_fifo);



    if (s->migration_blocker) {

        migrate_del_blocker(s->migration_blocker);

        error_free(s->migration_blocker);

    }



    if (s->shm_fd >= 0) {

        void *addr = memory_region_get_ram_ptr(&s->ivshmem);



        vmstate_unregister_ram(&s->ivshmem, DEVICE(dev));

        memory_region_del_subregion(&s->bar, &s->ivshmem);



        if (munmap(addr, s->ivshmem_size) == -1) {

            error_report("Failed to munmap shared memory %s", strerror(errno));

        }

    }



    if (s->eventfd_chr) {

        for (i = 0; i < s->vectors; i++) {

            if (s->eventfd_chr[i]) {

                qemu_chr_free(s->eventfd_chr[i]);

            }

        }

        g_free(s->eventfd_chr);

    }



    if (s->peers) {

        for (i = 0; i < s->nb_peers; i++) {

            close_peer_eventfds(s, i);

        }

        g_free(s->peers);

    }



    if (ivshmem_has_feature(s, IVSHMEM_MSI)) {

        msix_uninit_exclusive_bar(dev);

    }



    g_free(s->eventfd_table);

}

static void vmgenid_set_guid_test(void)

{

    QemuUUID expected, measured;

    gchar *cmd;



    g_assert(qemu_uuid_parse(VGID_GUID, &expected) == 0);



    cmd = g_strdup_printf("-machine accel=tcg -device vmgenid,id=testvgid,"

                          "guid=%s", VGID_GUID);

    qtest_start(cmd);



    /* Read the GUID from accessing guest memory */

    read_guid_from_memory(&measured);

    g_assert(memcmp(measured.data, expected.data, sizeof(measured.data)) == 0);



    qtest_quit(global_qtest);

    g_free(cmd);

}

static void rtas_start_cpu(PowerPCCPU *cpu_, sPAPRMachineState *spapr,
                           uint32_t token, uint32_t nargs,
                           target_ulong args,
                           uint32_t nret, target_ulong rets)
{
    target_ulong id, start, r3;
    PowerPCCPU *cpu;
    if (nargs != 3 || nret != 1) {
        rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);
        return;
    }
    id = rtas_ld(args, 0);
    start = rtas_ld(args, 1);
    r3 = rtas_ld(args, 2);
    cpu = spapr_find_cpu(id);
    if (cpu != NULL) {
        CPUState *cs = CPU(cpu);
        CPUPPCState *env = &cpu->env;
        PowerPCCPUClass *pcc = POWERPC_CPU_GET_CLASS(cpu);
        if (!cs->halted) {
            rtas_st(rets, 0, RTAS_OUT_HW_ERROR);
            return;
        }
        /* This will make sure qemu state is up to date with kvm, and
         * mark it dirty so our changes get flushed back before the
         * new cpu enters */
        kvm_cpu_synchronize_state(cs);
        env->msr = (1ULL << MSR_SF) | (1ULL << MSR_ME);
        env->nip = start;
        env->gpr[3] = r3;
        cs->halted = 0;
        spapr_cpu_set_endianness(cpu);
        spapr_cpu_update_tb_offset(cpu);
        qemu_cpu_kick(cs);
        rtas_st(rets, 0, RTAS_OUT_SUCCESS);
        return;
    }
    /* Didn't find a matching cpu */
    rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);
}

