static bool sensor_type_is_dr(uint32_t sensor_type)

{

    switch (sensor_type) {

    case RTAS_SENSOR_TYPE_ISOLATION_STATE:

    case RTAS_SENSOR_TYPE_DR:

    case RTAS_SENSOR_TYPE_ALLOCATION_STATE:

        return true;

    }



    return false;

}

static int tcg_match_add2i(TCGType type, tcg_target_long val)

{

    if (facilities & FACILITY_EXT_IMM) {

        if (type == TCG_TYPE_I32) {

            return 1;

        } else if (val >= -0xffffffffll && val <= 0xffffffffll) {

            return 1;

        }

    }

    return 0;

}

yuv2rgb_full_X_c_template(SwsContext *c, const int16_t *lumFilter,

                          const int16_t **lumSrc, int lumFilterSize,

                          const int16_t *chrFilter, const int16_t **chrUSrc,

                          const int16_t **chrVSrc, int chrFilterSize,

                          const int16_t **alpSrc, uint8_t *dest,

                          int dstW, int y, enum AVPixelFormat target, int hasAlpha)

{

    int i;

    int step = (target == AV_PIX_FMT_RGB24 || target == AV_PIX_FMT_BGR24) ? 3 : 4;

    int err[4] = {0};



    if(   target == AV_PIX_FMT_BGR4_BYTE || target == AV_PIX_FMT_RGB4_BYTE

       || target == AV_PIX_FMT_BGR8      || target == AV_PIX_FMT_RGB8)

        step = 1;



    for (i = 0; i < dstW; i++) {

        int j;

        int Y = 1<<9;

        int U = (1<<9)-(128 << 19);

        int V = (1<<9)-(128 << 19);

        int A;



        for (j = 0; j < lumFilterSize; j++) {

            Y += lumSrc[j][i] * lumFilter[j];

        }

        for (j = 0; j < chrFilterSize; j++) {

            U += chrUSrc[j][i] * chrFilter[j];

            V += chrVSrc[j][i] * chrFilter[j];

        }

        Y >>= 10;

        U >>= 10;

        V >>= 10;

        if (hasAlpha) {

            A = 1 << 18;

            for (j = 0; j < lumFilterSize; j++) {

                A += alpSrc[j][i] * lumFilter[j];

            }

            A >>= 19;

            if (A & 0x100)

                A = av_clip_uint8(A);

        }

        yuv2rgb_write_full(c, dest, i, Y, A, U, V, y, target, hasAlpha, err);

        dest += step;

    }

    c->dither_error[0][i] = err[0];

    c->dither_error[1][i] = err[1];

    c->dither_error[2][i] = err[2];

}

static uint32_t virtio_net_bad_features(VirtIODevice *vdev)

{

    uint32_t features = 0;



    /* Linux kernel 2.6.25.  It understood MAC (as everyone must),

     * but also these: */

    features |= (1 << VIRTIO_NET_F_MAC);

    features |= (1 << VIRTIO_NET_F_CSUM);

    features |= (1 << VIRTIO_NET_F_HOST_TSO4);

    features |= (1 << VIRTIO_NET_F_HOST_TSO6);

    features |= (1 << VIRTIO_NET_F_HOST_ECN);



    return features;

}

static void vga_isa_realizefn(DeviceState *dev, Error **errp)

{

    ISADevice *isadev = ISA_DEVICE(dev);

    ISAVGAState *d = ISA_VGA(dev);

    VGACommonState *s = &d->state;

    MemoryRegion *vga_io_memory;

    const MemoryRegionPortio *vga_ports, *vbe_ports;



    vga_common_init(s, OBJECT(dev), true);

    s->legacy_address_space = isa_address_space(isadev);

    vga_io_memory = vga_init_io(s, OBJECT(dev), &vga_ports, &vbe_ports);

    isa_register_portio_list(isadev, 0x3b0, vga_ports, s, "vga");

    if (vbe_ports) {

        isa_register_portio_list(isadev, 0x1ce, vbe_ports, s, "vbe");

    }

    memory_region_add_subregion_overlap(isa_address_space(isadev),

                                        0x000a0000,

                                        vga_io_memory, 1);

    memory_region_set_coalescing(vga_io_memory);

    s->con = graphic_console_init(DEVICE(dev), 0, s->hw_ops, s);



    vga_init_vbe(s, OBJECT(dev), isa_address_space(isadev));

    /* ROM BIOS */

    rom_add_vga(VGABIOS_FILENAME);

}

static DisasJumpType translate_one(DisasContext *ctx, uint32_t insn)

{

    int32_t disp21, disp16, disp12 __attribute__((unused));

    uint16_t fn11;

    uint8_t opc, ra, rb, rc, fpfn, fn7, lit;

    bool islit, real_islit;

    TCGv va, vb, vc, tmp, tmp2;

    TCGv_i32 t32;

    DisasJumpType ret;



    /* Decode all instruction fields */

    opc = extract32(insn, 26, 6);

    ra = extract32(insn, 21, 5);

    rb = extract32(insn, 16, 5);

    rc = extract32(insn, 0, 5);

    real_islit = islit = extract32(insn, 12, 1);

    lit = extract32(insn, 13, 8);



    disp21 = sextract32(insn, 0, 21);

    disp16 = sextract32(insn, 0, 16);

    disp12 = sextract32(insn, 0, 12);



    fn11 = extract32(insn, 5, 11);

    fpfn = extract32(insn, 5, 6);

    fn7 = extract32(insn, 5, 7);



    if (rb == 31 && !islit) {

        islit = true;

        lit = 0;

    }



    ret = DISAS_NEXT;

    switch (opc) {

    case 0x00:

        /* CALL_PAL */

        ret = gen_call_pal(ctx, insn & 0x03ffffff);

        break;

    case 0x01:

        /* OPC01 */

        goto invalid_opc;

    case 0x02:

        /* OPC02 */

        goto invalid_opc;

    case 0x03:

        /* OPC03 */

        goto invalid_opc;

    case 0x04:

        /* OPC04 */

        goto invalid_opc;

    case 0x05:

        /* OPC05 */

        goto invalid_opc;

    case 0x06:

        /* OPC06 */

        goto invalid_opc;

    case 0x07:

        /* OPC07 */

        goto invalid_opc;



    case 0x09:

        /* LDAH */

        disp16 = (uint32_t)disp16 << 16;

        /* fall through */

    case 0x08:

        /* LDA */

        va = dest_gpr(ctx, ra);

        /* It's worth special-casing immediate loads.  */

        if (rb == 31) {

            tcg_gen_movi_i64(va, disp16);

        } else {

            tcg_gen_addi_i64(va, load_gpr(ctx, rb), disp16);

        }

        break;



    case 0x0A:

        /* LDBU */

        REQUIRE_AMASK(BWX);

        gen_load_mem(ctx, &tcg_gen_qemu_ld8u, ra, rb, disp16, 0, 0);

        break;

    case 0x0B:

        /* LDQ_U */

        gen_load_mem(ctx, &tcg_gen_qemu_ld64, ra, rb, disp16, 0, 1);

        break;

    case 0x0C:

        /* LDWU */

        REQUIRE_AMASK(BWX);

        gen_load_mem(ctx, &tcg_gen_qemu_ld16u, ra, rb, disp16, 0, 0);

        break;

    case 0x0D:

        /* STW */

        REQUIRE_AMASK(BWX);

        gen_store_mem(ctx, &tcg_gen_qemu_st16, ra, rb, disp16, 0, 0);

        break;

    case 0x0E:

        /* STB */

        REQUIRE_AMASK(BWX);

        gen_store_mem(ctx, &tcg_gen_qemu_st8, ra, rb, disp16, 0, 0);

        break;

    case 0x0F:

        /* STQ_U */

        gen_store_mem(ctx, &tcg_gen_qemu_st64, ra, rb, disp16, 0, 1);

        break;



    case 0x10:

        vc = dest_gpr(ctx, rc);

        vb = load_gpr_lit(ctx, rb, lit, islit);



        if (ra == 31) {

            if (fn7 == 0x00) {

                /* Special case ADDL as SEXTL.  */

                tcg_gen_ext32s_i64(vc, vb);

                break;

            }

            if (fn7 == 0x29) {

                /* Special case SUBQ as NEGQ.  */

                tcg_gen_neg_i64(vc, vb);

                break;

            }

        }



        va = load_gpr(ctx, ra);

        switch (fn7) {

        case 0x00:

            /* ADDL */

            tcg_gen_add_i64(vc, va, vb);

            tcg_gen_ext32s_i64(vc, vc);

            break;

        case 0x02:

            /* S4ADDL */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 2);

            tcg_gen_add_i64(tmp, tmp, vb);

            tcg_gen_ext32s_i64(vc, tmp);

            tcg_temp_free(tmp);

            break;

        case 0x09:

            /* SUBL */

            tcg_gen_sub_i64(vc, va, vb);

            tcg_gen_ext32s_i64(vc, vc);

            break;

        case 0x0B:

            /* S4SUBL */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 2);

            tcg_gen_sub_i64(tmp, tmp, vb);

            tcg_gen_ext32s_i64(vc, tmp);

            tcg_temp_free(tmp);

            break;

        case 0x0F:

            /* CMPBGE */

            if (ra == 31) {

                /* Special case 0 >= X as X == 0.  */

                gen_helper_cmpbe0(vc, vb);

            } else {

                gen_helper_cmpbge(vc, va, vb);

            }

            break;

        case 0x12:

            /* S8ADDL */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 3);

            tcg_gen_add_i64(tmp, tmp, vb);

            tcg_gen_ext32s_i64(vc, tmp);

            tcg_temp_free(tmp);

            break;

        case 0x1B:

            /* S8SUBL */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 3);

            tcg_gen_sub_i64(tmp, tmp, vb);

            tcg_gen_ext32s_i64(vc, tmp);

            tcg_temp_free(tmp);

            break;

        case 0x1D:

            /* CMPULT */

            tcg_gen_setcond_i64(TCG_COND_LTU, vc, va, vb);

            break;

        case 0x20:

            /* ADDQ */

            tcg_gen_add_i64(vc, va, vb);

            break;

        case 0x22:

            /* S4ADDQ */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 2);

            tcg_gen_add_i64(vc, tmp, vb);

            tcg_temp_free(tmp);

            break;

        case 0x29:

            /* SUBQ */

            tcg_gen_sub_i64(vc, va, vb);

            break;

        case 0x2B:

            /* S4SUBQ */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 2);

            tcg_gen_sub_i64(vc, tmp, vb);

            tcg_temp_free(tmp);

            break;

        case 0x2D:

            /* CMPEQ */

            tcg_gen_setcond_i64(TCG_COND_EQ, vc, va, vb);

            break;

        case 0x32:

            /* S8ADDQ */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 3);

            tcg_gen_add_i64(vc, tmp, vb);

            tcg_temp_free(tmp);

            break;

        case 0x3B:

            /* S8SUBQ */

            tmp = tcg_temp_new();

            tcg_gen_shli_i64(tmp, va, 3);

            tcg_gen_sub_i64(vc, tmp, vb);

            tcg_temp_free(tmp);

            break;

        case 0x3D:

            /* CMPULE */

            tcg_gen_setcond_i64(TCG_COND_LEU, vc, va, vb);

            break;

        case 0x40:

            /* ADDL/V */

            tmp = tcg_temp_new();

            tcg_gen_ext32s_i64(tmp, va);

            tcg_gen_ext32s_i64(vc, vb);

            tcg_gen_add_i64(tmp, tmp, vc);

            tcg_gen_ext32s_i64(vc, tmp);

            gen_helper_check_overflow(cpu_env, vc, tmp);

            tcg_temp_free(tmp);

            break;

        case 0x49:

            /* SUBL/V */

            tmp = tcg_temp_new();

            tcg_gen_ext32s_i64(tmp, va);

            tcg_gen_ext32s_i64(vc, vb);

            tcg_gen_sub_i64(tmp, tmp, vc);

            tcg_gen_ext32s_i64(vc, tmp);

            gen_helper_check_overflow(cpu_env, vc, tmp);

            tcg_temp_free(tmp);

            break;

        case 0x4D:

            /* CMPLT */

            tcg_gen_setcond_i64(TCG_COND_LT, vc, va, vb);

            break;

        case 0x60:

            /* ADDQ/V */

            tmp = tcg_temp_new();

            tmp2 = tcg_temp_new();

            tcg_gen_eqv_i64(tmp, va, vb);

            tcg_gen_mov_i64(tmp2, va);

            tcg_gen_add_i64(vc, va, vb);

            tcg_gen_xor_i64(tmp2, tmp2, vc);

            tcg_gen_and_i64(tmp, tmp, tmp2);

            tcg_gen_shri_i64(tmp, tmp, 63);

            tcg_gen_movi_i64(tmp2, 0);

            gen_helper_check_overflow(cpu_env, tmp, tmp2);

            tcg_temp_free(tmp);

            tcg_temp_free(tmp2);

            break;

        case 0x69:

            /* SUBQ/V */

            tmp = tcg_temp_new();

            tmp2 = tcg_temp_new();

            tcg_gen_xor_i64(tmp, va, vb);

            tcg_gen_mov_i64(tmp2, va);

            tcg_gen_sub_i64(vc, va, vb);

            tcg_gen_xor_i64(tmp2, tmp2, vc);

            tcg_gen_and_i64(tmp, tmp, tmp2);

            tcg_gen_shri_i64(tmp, tmp, 63);

            tcg_gen_movi_i64(tmp2, 0);

            gen_helper_check_overflow(cpu_env, tmp, tmp2);

            tcg_temp_free(tmp);

            tcg_temp_free(tmp2);

            break;

        case 0x6D:

            /* CMPLE */

            tcg_gen_setcond_i64(TCG_COND_LE, vc, va, vb);

            break;

        default:

            goto invalid_opc;

        }

        break;



    case 0x11:

        if (fn7 == 0x20) {

            if (rc == 31) {

                /* Special case BIS as NOP.  */

                break;

            }

            if (ra == 31) {

                /* Special case BIS as MOV.  */

                vc = dest_gpr(ctx, rc);

                if (islit) {

                    tcg_gen_movi_i64(vc, lit);

                } else {

                    tcg_gen_mov_i64(vc, load_gpr(ctx, rb));

                }

                break;

            }

        }



        vc = dest_gpr(ctx, rc);

        vb = load_gpr_lit(ctx, rb, lit, islit);



        if (fn7 == 0x28 && ra == 31) {

            /* Special case ORNOT as NOT.  */

            tcg_gen_not_i64(vc, vb);

            break;

        }



        va = load_gpr(ctx, ra);

        switch (fn7) {

        case 0x00:

            /* AND */

            tcg_gen_and_i64(vc, va, vb);

            break;

        case 0x08:

            /* BIC */

            tcg_gen_andc_i64(vc, va, vb);

            break;

        case 0x14:

            /* CMOVLBS */

            tmp = tcg_temp_new();

            tcg_gen_andi_i64(tmp, va, 1);

            tcg_gen_movcond_i64(TCG_COND_NE, vc, tmp, load_zero(ctx),

                                vb, load_gpr(ctx, rc));

            tcg_temp_free(tmp);

            break;

        case 0x16:

            /* CMOVLBC */

            tmp = tcg_temp_new();

            tcg_gen_andi_i64(tmp, va, 1);

            tcg_gen_movcond_i64(TCG_COND_EQ, vc, tmp, load_zero(ctx),

                                vb, load_gpr(ctx, rc));

            tcg_temp_free(tmp);

            break;

        case 0x20:

            /* BIS */

            tcg_gen_or_i64(vc, va, vb);

            break;

        case 0x24:

            /* CMOVEQ */

            tcg_gen_movcond_i64(TCG_COND_EQ, vc, va, load_zero(ctx),

                                vb, load_gpr(ctx, rc));

            break;

        case 0x26:

            /* CMOVNE */

            tcg_gen_movcond_i64(TCG_COND_NE, vc, va, load_zero(ctx),

                                vb, load_gpr(ctx, rc));

            break;

        case 0x28:

            /* ORNOT */

            tcg_gen_orc_i64(vc, va, vb);

            break;

        case 0x40:

            /* XOR */

            tcg_gen_xor_i64(vc, va, vb);

            break;

        case 0x44:

            /* CMOVLT */

            tcg_gen_movcond_i64(TCG_COND_LT, vc, va, load_zero(ctx),

                                vb, load_gpr(ctx, rc));

            break;

        case 0x46:

            /* CMOVGE */

            tcg_gen_movcond_i64(TCG_COND_GE, vc, va, load_zero(ctx),

                                vb, load_gpr(ctx, rc));

            break;

        case 0x48:

            /* EQV */

