            REQUIRE_AMASK(MVI);

            REQUIRE_NO_LIT;

            va = load_gpr(ctx, ra);

            gen_helper_perr(vc, va, vb);

            break;

        case 0x32:

            /* CTLZ */

            REQUIRE_AMASK(CIX);

            REQUIRE_REG_31(ra);

            REQUIRE_NO_LIT;

            tcg_gen_clzi_i64(vc, vb, 64);

            break;

        case 0x33:

            /* CTTZ */

            REQUIRE_AMASK(CIX);

            REQUIRE_REG_31(ra);

            REQUIRE_NO_LIT;

            tcg_gen_ctzi_i64(vc, vb, 64);

            break;

        case 0x34:

            /* UNPKBW */

            REQUIRE_AMASK(MVI);

            REQUIRE_REG_31(ra);

            REQUIRE_NO_LIT;

            gen_helper_unpkbw(vc, vb);

            break;

        case 0x35:

            /* UNPKBL */

            REQUIRE_AMASK(MVI);

            REQUIRE_REG_31(ra);

            REQUIRE_NO_LIT;

            gen_helper_unpkbl(vc, vb);

            break;

        case 0x36:

            /* PKWB */

            REQUIRE_AMASK(MVI);

            REQUIRE_REG_31(ra);

            REQUIRE_NO_LIT;

            gen_helper_pkwb(vc, vb);

            break;

        case 0x37:

            /* PKLB */

            REQUIRE_AMASK(MVI);

            REQUIRE_REG_31(ra);

            REQUIRE_NO_LIT;

            gen_helper_pklb(vc, vb);

            break;

        case 0x38:

            /* MINSB8 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_minsb8(vc, va, vb);

            break;

        case 0x39:

            /* MINSW4 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_minsw4(vc, va, vb);

            break;

        case 0x3A:

            /* MINUB8 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_minub8(vc, va, vb);

            break;

        case 0x3B:

            /* MINUW4 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_minuw4(vc, va, vb);

            break;

        case 0x3C:

            /* MAXUB8 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_maxub8(vc, va, vb);

            break;

        case 0x3D:

            /* MAXUW4 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_maxuw4(vc, va, vb);

            break;

        case 0x3E:

            /* MAXSB8 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_maxsb8(vc, va, vb);

            break;

        case 0x3F:

            /* MAXSW4 */

            REQUIRE_AMASK(MVI);

            va = load_gpr(ctx, ra);

            gen_helper_maxsw4(vc, va, vb);

            break;

        default:

            goto invalid_opc;

        }

        break;



    case 0x1D:

        /* HW_MTPR (PALcode) */

#ifndef CONFIG_USER_ONLY

        REQUIRE_TB_FLAG(ENV_FLAG_PAL_MODE);

        vb = load_gpr(ctx, rb);

        ret = gen_mtpr(ctx, vb, insn & 0xffff);

        break;

#else

        goto invalid_opc;

#endif



    case 0x1E:

        /* HW_RET (PALcode) */

#ifndef CONFIG_USER_ONLY

        REQUIRE_TB_FLAG(ENV_FLAG_PAL_MODE);

        if (rb == 31) {

            /* Pre-EV6 CPUs interpreted this as HW_REI, loading the return

               address from EXC_ADDR.  This turns out to be useful for our

               emulation PALcode, so continue to accept it.  */

            ctx->lit = vb = tcg_temp_new();

            tcg_gen_ld_i64(vb, cpu_env, offsetof(CPUAlphaState, exc_addr));

        } else {

            vb = load_gpr(ctx, rb);

        }

        tcg_gen_movi_i64(cpu_lock_addr, -1);

        tmp = tcg_temp_new();

        tcg_gen_movi_i64(tmp, 0);

        st_flag_byte(tmp, ENV_FLAG_RX_SHIFT);

        tcg_gen_andi_i64(tmp, vb, 1);

        st_flag_byte(tmp, ENV_FLAG_PAL_SHIFT);

        tcg_temp_free(tmp);

        tcg_gen_andi_i64(cpu_pc, vb, ~3);

        /* Allow interrupts to be recognized right away.  */

        ret = DISAS_PC_UPDATED_NOCHAIN;

        break;

#else

        goto invalid_opc;

#endif



    case 0x1F:

        /* HW_ST (PALcode) */

#ifndef CONFIG_USER_ONLY

        REQUIRE_TB_FLAG(ENV_FLAG_PAL_MODE);

        {

            switch ((insn >> 12) & 0xF) {

            case 0x0:

                /* Longword physical access */

                va = load_gpr(ctx, ra);

                vb = load_gpr(ctx, rb);

                tmp = tcg_temp_new();

                tcg_gen_addi_i64(tmp, vb, disp12);

                tcg_gen_qemu_st_i64(va, tmp, MMU_PHYS_IDX, MO_LESL);

                tcg_temp_free(tmp);

                break;

            case 0x1:

                /* Quadword physical access */

                va = load_gpr(ctx, ra);

                vb = load_gpr(ctx, rb);

                tmp = tcg_temp_new();

                tcg_gen_addi_i64(tmp, vb, disp12);

                tcg_gen_qemu_st_i64(va, tmp, MMU_PHYS_IDX, MO_LEQ);

                tcg_temp_free(tmp);

                break;

            case 0x2:

                /* Longword physical access with lock */

                ret = gen_store_conditional(ctx, ra, rb, disp12,

                                            MMU_PHYS_IDX, MO_LESL);

                break;

            case 0x3:

                /* Quadword physical access with lock */

                ret = gen_store_conditional(ctx, ra, rb, disp12,

                                            MMU_PHYS_IDX, MO_LEQ);

                break;

            case 0x4:

                /* Longword virtual access */

                goto invalid_opc;

            case 0x5:

                /* Quadword virtual access */

                goto invalid_opc;

            case 0x6:

                /* Invalid */

                goto invalid_opc;

            case 0x7:

                /* Invalid */

                goto invalid_opc;

            case 0x8:

                /* Invalid */

                goto invalid_opc;

            case 0x9:

                /* Invalid */

                goto invalid_opc;

            case 0xA:

                /* Invalid */

                goto invalid_opc;

            case 0xB:

                /* Invalid */

                goto invalid_opc;

            case 0xC:

                /* Longword virtual access with alternate access mode */

                goto invalid_opc;

            case 0xD:

                /* Quadword virtual access with alternate access mode */

                goto invalid_opc;

            case 0xE:

                /* Invalid */

                goto invalid_opc;

            case 0xF:

                /* Invalid */

                goto invalid_opc;

            }

            break;

        }

#else

        goto invalid_opc;

#endif

    case 0x20:

        /* LDF */

        gen_load_mem(ctx, &gen_qemu_ldf, ra, rb, disp16, 1, 0);

        break;

    case 0x21:

        /* LDG */

        gen_load_mem(ctx, &gen_qemu_ldg, ra, rb, disp16, 1, 0);

        break;

    case 0x22:

        /* LDS */

        gen_load_mem(ctx, &gen_qemu_lds, ra, rb, disp16, 1, 0);

        break;

    case 0x23:

        /* LDT */

        gen_load_mem(ctx, &tcg_gen_qemu_ld64, ra, rb, disp16, 1, 0);

        break;

    case 0x24:

        /* STF */

        gen_store_mem(ctx, &gen_qemu_stf, ra, rb, disp16, 1, 0);

        break;

    case 0x25:

        /* STG */

        gen_store_mem(ctx, &gen_qemu_stg, ra, rb, disp16, 1, 0);

        break;

    case 0x26:

        /* STS */

        gen_store_mem(ctx, &gen_qemu_sts, ra, rb, disp16, 1, 0);

        break;

    case 0x27:

        /* STT */

        gen_store_mem(ctx, &tcg_gen_qemu_st64, ra, rb, disp16, 1, 0);

        break;

    case 0x28:

        /* LDL */

        gen_load_mem(ctx, &tcg_gen_qemu_ld32s, ra, rb, disp16, 0, 0);

        break;

    case 0x29:

        /* LDQ */

        gen_load_mem(ctx, &tcg_gen_qemu_ld64, ra, rb, disp16, 0, 0);

        break;

    case 0x2A:

        /* LDL_L */

        gen_load_mem(ctx, &gen_qemu_ldl_l, ra, rb, disp16, 0, 0);

        break;

    case 0x2B:

        /* LDQ_L */

        gen_load_mem(ctx, &gen_qemu_ldq_l, ra, rb, disp16, 0, 0);

        break;

    case 0x2C:

        /* STL */

        gen_store_mem(ctx, &tcg_gen_qemu_st32, ra, rb, disp16, 0, 0);

        break;

    case 0x2D:

        /* STQ */

        gen_store_mem(ctx, &tcg_gen_qemu_st64, ra, rb, disp16, 0, 0);

        break;

    case 0x2E:

        /* STL_C */

        ret = gen_store_conditional(ctx, ra, rb, disp16,

                                    ctx->mem_idx, MO_LESL);

        break;

    case 0x2F:

        /* STQ_C */

        ret = gen_store_conditional(ctx, ra, rb, disp16,

                                    ctx->mem_idx, MO_LEQ);

        break;

    case 0x30:

        /* BR */

        ret = gen_bdirect(ctx, ra, disp21);

        break;

    case 0x31: /* FBEQ */

        ret = gen_fbcond(ctx, TCG_COND_EQ, ra, disp21);

        break;

    case 0x32: /* FBLT */

        ret = gen_fbcond(ctx, TCG_COND_LT, ra, disp21);

        break;

    case 0x33: /* FBLE */

        ret = gen_fbcond(ctx, TCG_COND_LE, ra, disp21);

        break;

    case 0x34:

        /* BSR */

        ret = gen_bdirect(ctx, ra, disp21);

        break;

    case 0x35: /* FBNE */

        ret = gen_fbcond(ctx, TCG_COND_NE, ra, disp21);

        break;

    case 0x36: /* FBGE */

        ret = gen_fbcond(ctx, TCG_COND_GE, ra, disp21);

        break;

    case 0x37: /* FBGT */

        ret = gen_fbcond(ctx, TCG_COND_GT, ra, disp21);

        break;

    case 0x38:

        /* BLBC */

        ret = gen_bcond(ctx, TCG_COND_EQ, ra, disp21, 1);

        break;

    case 0x39:

        /* BEQ */

        ret = gen_bcond(ctx, TCG_COND_EQ, ra, disp21, 0);

        break;

    case 0x3A:

        /* BLT */

        ret = gen_bcond(ctx, TCG_COND_LT, ra, disp21, 0);

        break;

    case 0x3B:

        /* BLE */

        ret = gen_bcond(ctx, TCG_COND_LE, ra, disp21, 0);

        break;

    case 0x3C:

        /* BLBS */

        ret = gen_bcond(ctx, TCG_COND_NE, ra, disp21, 1);

        break;

    case 0x3D:

        /* BNE */

        ret = gen_bcond(ctx, TCG_COND_NE, ra, disp21, 0);

        break;

    case 0x3E:

        /* BGE */

        ret = gen_bcond(ctx, TCG_COND_GE, ra, disp21, 0);

        break;

    case 0x3F:

        /* BGT */

        ret = gen_bcond(ctx, TCG_COND_GT, ra, disp21, 0);

        break;

    invalid_opc:

        ret = gen_invalid(ctx);

        break;

    }



    return ret;

}

void cpu_x86_update_cr4(CPUX86State *env, uint32_t new_cr4)

{

#if defined(DEBUG_MMU)

    printf("CR4 update: CR4=%08x\n", (uint32_t)env->cr[4]);

#endif

    if ((new_cr4 & (CR4_PGE_MASK | CR4_PAE_MASK | CR4_PSE_MASK)) !=

        (env->cr[4] & (CR4_PGE_MASK | CR4_PAE_MASK | CR4_PSE_MASK))) {

        tlb_flush(env, 1);

    }

    /* SSE handling */

    if (!(env->cpuid_features & CPUID_SSE))

        new_cr4 &= ~CR4_OSFXSR_MASK;

    if (new_cr4 & CR4_OSFXSR_MASK)

        env->hflags |= HF_OSFXSR_MASK;

    else

        env->hflags &= ~HF_OSFXSR_MASK;



    env->cr[4] = new_cr4;

}

static void mxf_write_package(AVFormatContext *s, enum MXFMetadataSetType type, const char *package_name)

{

    MXFContext *mxf = s->priv_data;

    AVIOContext *pb = s->pb;

    int i, track_count = s->nb_streams+1;

    int name_size = mxf_utf16_local_tag_length(package_name);

    int user_comment_count = 0;



    if (type == MaterialPackage) {

        if (mxf->store_user_comments)

            user_comment_count = mxf_write_user_comments(s, s->metadata);

        mxf_write_metadata_key(pb, 0x013600);

        PRINT_KEY(s, "Material Package key", pb->buf_ptr - 16);

        klv_encode_ber_length(pb, 92 + name_size + (16*track_count) + (16*user_comment_count) + 12*mxf->store_user_comments);

    } else {

        mxf_write_metadata_key(pb, 0x013700);

        PRINT_KEY(s, "Source Package key", pb->buf_ptr - 16);

        klv_encode_ber_length(pb, 112 + name_size + (16*track_count) + 12*mxf->store_user_comments); // 20 bytes length for descriptor reference

    }



    // write uid

    mxf_write_local_tag(pb, 16, 0x3C0A);

    mxf_write_uuid(pb, type, 0);

    av_log(s,AV_LOG_DEBUG, "package type:%d\n", type);

    PRINT_KEY(s, "package uid", pb->buf_ptr - 16);



    // write package umid

    mxf_write_local_tag(pb, 32, 0x4401);

    mxf_write_umid(s, type == SourcePackage);

    PRINT_KEY(s, "package umid second part", pb->buf_ptr - 16);



    // package name

    if (name_size)

        mxf_write_local_tag_utf16(pb, 0x4402, package_name);



    // package creation date

    mxf_write_local_tag(pb, 8, 0x4405);

    avio_wb64(pb, mxf->timestamp);



    // package modified date

    mxf_write_local_tag(pb, 8, 0x4404);

    avio_wb64(pb, mxf->timestamp);



    // write track refs

    mxf_write_local_tag(pb, track_count*16 + 8, 0x4403);

    mxf_write_refs_count(pb, track_count);

    mxf_write_uuid(pb, type == MaterialPackage ? Track :

                   Track + TypeBottom, -1); // timecode track

    for (i = 0; i < s->nb_streams; i++)

        mxf_write_uuid(pb, type == MaterialPackage ? Track : Track + TypeBottom, i);



    // write user comment refs

    if (mxf->store_user_comments) {

        mxf_write_local_tag(pb, user_comment_count*16 + 8, 0x4406);

        mxf_write_refs_count(pb, user_comment_count);

        for (i = 0; i < user_comment_count; i++)

            mxf_write_uuid(pb, TaggedValue, mxf->tagged_value_count - user_comment_count + i);

    }



    // write multiple descriptor reference

    if (type == SourcePackage) {

        mxf_write_local_tag(pb, 16, 0x4701);

        if (s->nb_streams > 1) {

            mxf_write_uuid(pb, MultipleDescriptor, 0);

            mxf_write_multi_descriptor(s);

        } else

            mxf_write_uuid(pb, SubDescriptor, 0);

    }



    // write timecode track

    mxf_write_track(s, mxf->timecode_track, type);

    mxf_write_sequence(s, mxf->timecode_track, type);

    mxf_write_timecode_component(s, mxf->timecode_track, type);



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        mxf_write_track(s, st, type);

        mxf_write_sequence(s, st, type);

        mxf_write_structural_component(s, st, type);



        if (type == SourcePackage) {

            MXFStreamContext *sc = st->priv_data;

            mxf_essence_container_uls[sc->index].write_desc(s, st);

        }

    }

}

static void avc_luma_midv_qrt_16w_msa(const uint8_t *src, int32_t src_stride,

                                      uint8_t *dst, int32_t dst_stride,

                                      int32_t height, uint8_t vert_offset)

{

    uint32_t multiple8_cnt;



    for (multiple8_cnt = 2; multiple8_cnt--;) {

        avc_luma_midv_qrt_8w_msa(src, src_stride, dst, dst_stride, height,

                                 vert_offset);



        src += 8;

        dst += 8;

    }

}

int float32_lt_quiet( float32 a, float32 b STATUS_PARAM )

{

    flag aSign, bSign;



    if (    ( ( extractFloat32Exp( a ) == 0xFF ) && extractFloat32Frac( a ) )

         || ( ( extractFloat32Exp( b ) == 0xFF ) && extractFloat32Frac( b ) )

       ) {

        if ( float32_is_signaling_nan( a ) || float32_is_signaling_nan( b ) ) {

            float_raise( float_flag_invalid STATUS_VAR);

        }

        return 0;

    }

    aSign = extractFloat32Sign( a );

    bSign = extractFloat32Sign( b );

    if ( aSign != bSign ) return aSign && ( (bits32) ( ( a | b )<<1 ) != 0 );

    return ( a != b ) && ( aSign ^ ( a < b ) );



}

static av_always_inline int normal_limit(uint8_t *p, int stride, int E, int I)

{

    LOAD_PIXELS

    return simple_limit(p, stride, 2*E+I)

        && FFABS(p3-p2) <= I && FFABS(p2-p1) <= I && FFABS(p1-p0) <= I

        && FFABS(q3-q2) <= I && FFABS(q2-q1) <= I && FFABS(q1-q0) <= I;

}

static inline int check_ap(CPUARMState *env, ARMMMUIdx mmu_idx,

                           int ap, int domain_prot,

                           int access_type)

{

    int prot_ro;

    bool is_user = regime_is_user(env, mmu_idx);



    if (domain_prot == 3) {

        return PAGE_READ | PAGE_WRITE;

    }



    if (access_type == 1) {

        prot_ro = 0;

    } else {

        prot_ro = PAGE_READ;

    }



    switch (ap) {

    case 0:

        if (arm_feature(env, ARM_FEATURE_V7)) {

            return 0;

        }

        if (access_type == 1) {

            return 0;

        }

        switch (regime_sctlr(env, mmu_idx) & (SCTLR_S | SCTLR_R)) {

        case SCTLR_S:

            return is_user ? 0 : PAGE_READ;

        case SCTLR_R:

            return PAGE_READ;

        default:

            return 0;

        }

    case 1:

        return is_user ? 0 : PAGE_READ | PAGE_WRITE;

    case 2:

        if (is_user) {

            return prot_ro;

        } else {

            return PAGE_READ | PAGE_WRITE;

        }

    case 3:

        return PAGE_READ | PAGE_WRITE;

    case 4: /* Reserved.  */

        return 0;

    case 5:

        return is_user ? 0 : prot_ro;

    case 6:

        return prot_ro;

    case 7:

        if (!arm_feature(env, ARM_FEATURE_V6K)) {

            return 0;

        }

        return prot_ro;

    default:

        abort();

    }

}

static AVFilterBufferRef *copy_buffer_ref(AVFilterContext *ctx,

                                          AVFilterBufferRef *ref)

{

    AVFilterLink *outlink = ctx->outputs[0];

    AVFilterBufferRef *buf;

    int channels, data_size, i;



    switch (outlink->type) {



    case AVMEDIA_TYPE_VIDEO:

        buf = avfilter_get_video_buffer(outlink, AV_PERM_WRITE,

                                        ref->video->w, ref->video->h);



        av_image_copy(buf->data, buf->linesize,

                      (void*)ref->data, ref->linesize,

                      ref->format, ref->video->w, ref->video->h);

        break;



    case AVMEDIA_TYPE_AUDIO:

        buf = ff_get_audio_buffer(outlink, AV_PERM_WRITE,

                                        ref->audio->nb_samples);



        channels = av_get_channel_layout_nb_channels(ref->audio->channel_layout);

        av_samples_copy(buf->extended_data, ref->buf->extended_data,

                        0, 0, ref->audio->nb_samples,

                        channels,

                        ref->format);

        break;



    default:


    }

    avfilter_copy_buffer_ref_props(buf, ref);

    return buf;

}

