static int get_range_off(int *off, int *y_rng, int *uv_rng,

                         enum AVColorRange rng, int depth)

{

    switch (rng) {

    case AVCOL_RANGE_MPEG:

        *off = 16 << (depth - 8);

        *y_rng = 219 << (depth - 8);

        *uv_rng = 224 << (depth - 8);

        break;

    case AVCOL_RANGE_JPEG:

        *off = 0;

        *y_rng = *uv_rng = (256 << (depth - 8)) - 1;

        break;

    default:

        return AVERROR(EINVAL);

    }



    return 0;

}

static int piix4_device_hotplug(DeviceState *qdev, PCIDevice *dev,

				PCIHotplugState state)

{

    int slot = PCI_SLOT(dev->devfn);

    PIIX4PMState *s = DO_UPCAST(PIIX4PMState, dev,

                                PCI_DEVICE(qdev));



    /* Don't send event when device is enabled during qemu machine creation:

     * it is present on boot, no hotplug event is necessary. We do send an

     * event when the device is disabled later. */

    if (state == PCI_COLDPLUG_ENABLED) {

        return 0;

    }



    s->pci0_status.up = 0;

    s->pci0_status.down = 0;

    if (state == PCI_HOTPLUG_ENABLED) {

        enable_device(s, slot);

    } else {

        disable_device(s, slot);

    }



    pm_update_sci(s);



    return 0;

}

static int vp8_lossless_decode_frame(AVCodecContext *avctx, AVFrame *p,

                                     int *got_frame, uint8_t *data_start,

                                     unsigned int data_size, int is_alpha_chunk)

{

    WebPContext *s = avctx->priv_data;

    int w, h, ret, i;



    if (!is_alpha_chunk) {

        s->lossless = 1;

        avctx->pix_fmt = AV_PIX_FMT_ARGB;

    }



    ret = init_get_bits8(&s->gb, data_start, data_size);

    if (ret < 0)

        return ret;



    if (!is_alpha_chunk) {

        if (get_bits(&s->gb, 8) != 0x2F) {

            av_log(avctx, AV_LOG_ERROR, "Invalid WebP Lossless signature\n");

            return AVERROR_INVALIDDATA;

        }



        w = get_bits(&s->gb, 14) + 1;

        h = get_bits(&s->gb, 14) + 1;

        if (s->width && s->width != w) {

            av_log(avctx, AV_LOG_WARNING, "Width mismatch. %d != %d\n",

                   s->width, w);

        }

        s->width = w;

        if (s->height && s->height != h) {

            av_log(avctx, AV_LOG_WARNING, "Height mismatch. %d != %d\n",

                   s->width, w);

        }

        s->height = h;



        ret = ff_set_dimensions(avctx, s->width, s->height);

        if (ret < 0)

            return ret;



        s->has_alpha = get_bits1(&s->gb);



        if (get_bits(&s->gb, 3) != 0x0) {

            av_log(avctx, AV_LOG_ERROR, "Invalid WebP Lossless version\n");

            return AVERROR_INVALIDDATA;

        }

    } else {

        if (!s->width || !s->height)

            return AVERROR_BUG;

        w = s->width;

        h = s->height;

    }



    /* parse transformations */

    s->nb_transforms = 0;

    s->reduced_width = 0;

    while (get_bits1(&s->gb)) {

        enum TransformType transform = get_bits(&s->gb, 2);

        s->transforms[s->nb_transforms++] = transform;

        switch (transform) {

        case PREDICTOR_TRANSFORM:

            ret = parse_transform_predictor(s);

            break;

        case COLOR_TRANSFORM:

            ret = parse_transform_color(s);

            break;

        case COLOR_INDEXING_TRANSFORM:

            ret = parse_transform_color_indexing(s);

            break;

        }

        if (ret < 0)

            goto free_and_return;

    }



    /* decode primary image */

    s->image[IMAGE_ROLE_ARGB].frame = p;

    if (is_alpha_chunk)

        s->image[IMAGE_ROLE_ARGB].is_alpha_primary = 1;

    ret = decode_entropy_coded_image(s, IMAGE_ROLE_ARGB, w, h);

    if (ret < 0)

        goto free_and_return;



    /* apply transformations */

    for (i = s->nb_transforms - 1; i >= 0; i--) {

        switch (s->transforms[i]) {

        case PREDICTOR_TRANSFORM:

            ret = apply_predictor_transform(s);

            break;

        case COLOR_TRANSFORM:

            ret = apply_color_transform(s);

            break;

        case SUBTRACT_GREEN:

            ret = apply_subtract_green_transform(s);

            break;

        case COLOR_INDEXING_TRANSFORM:

            ret = apply_color_indexing_transform(s);

            break;

        }

        if (ret < 0)

            goto free_and_return;

    }



    *got_frame   = 1;

    p->pict_type = AV_PICTURE_TYPE_I;

    p->key_frame = 1;

    ret          = data_size;



free_and_return:

    for (i = 0; i < IMAGE_ROLE_NB; i++)

        image_ctx_free(&s->image[i]);



    return ret;

}

static int cbs_mpeg2_read_unit(CodedBitstreamContext *ctx,

                               CodedBitstreamUnit *unit)

{

    BitstreamContext bc;

    int err;



    err = bitstream_init(&bc, unit->data, 8 * unit->data_size);

    if (err < 0)

        return err;



    if (MPEG2_START_IS_SLICE(unit->type)) {

        MPEG2RawSlice *slice;

        int pos, len;



        slice = av_mallocz(sizeof(*slice));

        if (!slice)

            return AVERROR(ENOMEM);

        err = cbs_mpeg2_read_slice_header(ctx, &bc, &slice->header);

        if (err < 0) {

            av_free(slice);

            return err;

        }



        pos = bitstream_tell(&bc);

        len = unit->data_size;



        slice->data_size = len - pos / 8;

        slice->data = av_malloc(slice->data_size);

        if (!slice->data) {

            av_free(slice);

            return AVERROR(ENOMEM);

        }



        memcpy(slice->data,

               unit->data + pos / 8, slice->data_size);

        slice->data_bit_start = pos % 8;



        unit->content = slice;



    } else {

        switch (unit->type) {

#define START(start_code, type, func) \

        case start_code: \

            { \

                type *header; \

                header = av_mallocz(sizeof(*header)); \

                if (!header) \

                    return AVERROR(ENOMEM); \

                err = cbs_mpeg2_read_ ## func(ctx, &bc, header); \

                if (err < 0) { \

                    av_free(header); \

                    return err; \

                } \

                unit->content = header; \

            } \

            break;

            START(0x00, MPEG2RawPictureHeader,  picture_header);

            START(0xb2, MPEG2RawUserData,       user_data);

            START(0xb3, MPEG2RawSequenceHeader, sequence_header);

            START(0xb5, MPEG2RawExtensionData,  extension_data);

            START(0xb8, MPEG2RawGroupOfPicturesHeader, group_of_pictures_header);

#undef START

        default:

            av_log(ctx->log_ctx, AV_LOG_ERROR, "Unknown start code %02x.\n",

                   unit->type);

            return AVERROR_INVALIDDATA;

        }

    }



    return 0;

}

