static int scan_mmco_reset(AVCodecParserContext *s, GetBitContext *gb,

                           void *logctx)

{

    H264PredWeightTable pwt;

    int slice_type_nos = s->pict_type & 3;

    H264ParseContext *p = s->priv_data;

    int list_count, ref_count[2];





    if (p->ps.pps->redundant_pic_cnt_present)

        get_ue_golomb(gb); // redundant_pic_count



    if (slice_type_nos == AV_PICTURE_TYPE_B)

        get_bits1(gb); // direct_spatial_mv_pred



    if (ff_h264_parse_ref_count(&list_count, ref_count, gb, p->ps.pps,

                                slice_type_nos, p->picture_structure, logctx) < 0)

        return AVERROR_INVALIDDATA;



    if (slice_type_nos != AV_PICTURE_TYPE_I) {

        int list;

        for (list = 0; list < list_count; list++) {

            if (get_bits1(gb)) {

                int index;

                for (index = 0; ; index++) {

                    unsigned int reordering_of_pic_nums_idc = get_ue_golomb_31(gb);



                    if (reordering_of_pic_nums_idc < 3)

                        get_ue_golomb_long(gb);

                    else if (reordering_of_pic_nums_idc > 3) {

                        av_log(logctx, AV_LOG_ERROR,

                               "illegal reordering_of_pic_nums_idc %d\n",

                               reordering_of_pic_nums_idc);

                        return AVERROR_INVALIDDATA;

                    } else

                        break;



                    if (index >= ref_count[list]) {

                        av_log(logctx, AV_LOG_ERROR,

                               "reference count %d overflow\n", index);

                        return AVERROR_INVALIDDATA;

                    }

                }

            }

        }

    }



    if ((p->ps.pps->weighted_pred && slice_type_nos == AV_PICTURE_TYPE_P) ||

        (p->ps.pps->weighted_bipred_idc == 1 && slice_type_nos == AV_PICTURE_TYPE_B))

        ff_h264_pred_weight_table(gb, p->ps.sps, ref_count, slice_type_nos,

                                  &pwt, logctx);



    if (get_bits1(gb)) { // adaptive_ref_pic_marking_mode_flag

        int i;

        for (i = 0; i < MAX_MMCO_COUNT; i++) {

            MMCOOpcode opcode = get_ue_golomb_31(gb);

            if (opcode > (unsigned) MMCO_LONG) {

                av_log(logctx, AV_LOG_ERROR,

                       "illegal memory management control operation %d\n",

                       opcode);

                return AVERROR_INVALIDDATA;

            }

            if (opcode == MMCO_END)

               return 0;

            else if (opcode == MMCO_RESET)

                return 1;



            if (opcode == MMCO_SHORT2UNUSED || opcode == MMCO_SHORT2LONG)

                get_ue_golomb_long(gb); // difference_of_pic_nums_minus1

            if (opcode == MMCO_SHORT2LONG || opcode == MMCO_LONG2UNUSED ||

                opcode == MMCO_LONG || opcode == MMCO_SET_MAX_LONG)

                get_ue_golomb_31(gb);

        }

    }



    return 0;

}

static av_always_inline void vc1_apply_p_v_loop_filter(VC1Context *v, int block_num)

{

    MpegEncContext *s  = &v->s;

    int mb_cbp         = v->cbp[s->mb_x - s->mb_stride],

        block_cbp      = mb_cbp      >> (block_num * 4), bottom_cbp,

        mb_is_intra    = v->is_intra[s->mb_x - s->mb_stride],

        block_is_intra = mb_is_intra >> (block_num * 4), bottom_is_intra;

    int idx, linesize  = block_num > 3 ? s->uvlinesize : s->linesize, ttblk;

    uint8_t *dst;



    if (block_num > 3) {

        dst      = s->dest[block_num - 3];

    } else {

        dst      = s->dest[0] + (block_num & 1) * 8 + ((block_num & 2) * 4 - 8) * linesize;

    }

    if (s->mb_y != s->end_mb_y || block_num < 2) {

        int16_t (*mv)[2];

        int mv_stride;



        if (block_num > 3) {

            bottom_cbp      = v->cbp[s->mb_x]      >> (block_num * 4);

            bottom_is_intra = v->is_intra[s->mb_x] >> (block_num * 4);

            mv              = &v->luma_mv[s->mb_x - s->mb_stride];

            mv_stride       = s->mb_stride;

        } else {

            bottom_cbp      = (block_num < 2) ? (mb_cbp               >> ((block_num + 2) * 4))

                                              : (v->cbp[s->mb_x]      >> ((block_num - 2) * 4));

            bottom_is_intra = (block_num < 2) ? (mb_is_intra          >> ((block_num + 2) * 4))

                                              : (v->is_intra[s->mb_x] >> ((block_num - 2) * 4));

            mv_stride       = s->b8_stride;

            mv              = &s->current_picture.motion_val[0][s->block_index[block_num] - 2 * mv_stride];

        }



        if (bottom_is_intra & 1 || block_is_intra & 1 ||

            mv[0][0] != mv[mv_stride][0] || mv[0][1] != mv[mv_stride][1]) {

            v->vc1dsp.vc1_v_loop_filter8(dst, linesize, v->pq);

        } else {

            idx = ((bottom_cbp >> 2) | block_cbp) & 3;

            if (idx == 3) {

                v->vc1dsp.vc1_v_loop_filter8(dst, linesize, v->pq);

            } else if (idx) {

                if (idx == 1)

                    v->vc1dsp.vc1_v_loop_filter4(dst + 4, linesize, v->pq);

                else

                    v->vc1dsp.vc1_v_loop_filter4(dst,     linesize, v->pq);

            }

        }

    }



    dst -= 4 * linesize;

    ttblk = (v->ttblk[s->mb_x - s->mb_stride] >> (block_num * 4)) & 0xF;

    if (ttblk == TT_4X4 || ttblk == TT_8X4) {

        idx = (block_cbp | (block_cbp >> 2)) & 3;

        if (idx == 3) {

            v->vc1dsp.vc1_v_loop_filter8(dst, linesize, v->pq);

        } else if (idx) {

            if (idx == 1)

                v->vc1dsp.vc1_v_loop_filter4(dst + 4, linesize, v->pq);

            else

                v->vc1dsp.vc1_v_loop_filter4(dst,     linesize, v->pq);

        }

    }

}

static int nvme_init(PCIDevice *pci_dev)

{

    NvmeCtrl *n = NVME(pci_dev);

    NvmeIdCtrl *id = &n->id_ctrl;



    int i;

    int64_t bs_size;

    uint8_t *pci_conf;



    if (!(n->conf.bs)) {

        return -1;

    }



    bs_size = bdrv_getlength(n->conf.bs);

    if (bs_size < 0) {

        return -1;

    }



    blkconf_serial(&n->conf, &n->serial);

    if (!n->serial) {

        return -1;

    }



    pci_conf = pci_dev->config;

    pci_conf[PCI_INTERRUPT_PIN] = 1;

    pci_config_set_prog_interface(pci_dev->config, 0x2);

    pci_config_set_class(pci_dev->config, PCI_CLASS_STORAGE_EXPRESS);

    pcie_endpoint_cap_init(&n->parent_obj, 0x80);



    n->num_namespaces = 1;

    n->num_queues = 64;

    n->reg_size = 1 << qemu_fls(0x1004 + 2 * (n->num_queues + 1) * 4);

    n->ns_size = bs_size / (uint64_t)n->num_namespaces;



    n->namespaces = g_malloc0(sizeof(*n->namespaces)*n->num_namespaces);

    n->sq = g_malloc0(sizeof(*n->sq)*n->num_queues);

    n->cq = g_malloc0(sizeof(*n->cq)*n->num_queues);



    memory_region_init_io(&n->iomem, OBJECT(n), &nvme_mmio_ops, n,

                          "nvme", n->reg_size);

    pci_register_bar(&n->parent_obj, 0,

        PCI_BASE_ADDRESS_SPACE_MEMORY | PCI_BASE_ADDRESS_MEM_TYPE_64,

        &n->iomem);

    msix_init_exclusive_bar(&n->parent_obj, n->num_queues, 4);



    id->vid = cpu_to_le16(pci_get_word(pci_conf + PCI_VENDOR_ID));

    id->ssvid = cpu_to_le16(pci_get_word(pci_conf + PCI_SUBSYSTEM_VENDOR_ID));

    strpadcpy((char *)id->mn, sizeof(id->mn), "QEMU NVMe Ctrl", ' ');

    strpadcpy((char *)id->fr, sizeof(id->fr), "1.0", ' ');

    strpadcpy((char *)id->sn, sizeof(id->sn), n->serial, ' ');

    id->rab = 6;

    id->ieee[0] = 0x00;

    id->ieee[1] = 0x02;

    id->ieee[2] = 0xb3;

    id->oacs = cpu_to_le16(0);

    id->frmw = 7 << 1;

    id->lpa = 1 << 0;

    id->sqes = (0x6 << 4) | 0x6;

    id->cqes = (0x4 << 4) | 0x4;

    id->nn = cpu_to_le32(n->num_namespaces);

    id->psd[0].mp = cpu_to_le16(0x9c4);

    id->psd[0].enlat = cpu_to_le32(0x10);

    id->psd[0].exlat = cpu_to_le32(0x4);



    n->bar.cap = 0;

    NVME_CAP_SET_MQES(n->bar.cap, 0x7ff);

    NVME_CAP_SET_CQR(n->bar.cap, 1);

    NVME_CAP_SET_AMS(n->bar.cap, 1);

    NVME_CAP_SET_TO(n->bar.cap, 0xf);

    NVME_CAP_SET_CSS(n->bar.cap, 1);



    n->bar.vs = 0x00010001;

    n->bar.intmc = n->bar.intms = 0;



    for (i = 0; i < n->num_namespaces; i++) {

        NvmeNamespace *ns = &n->namespaces[i];

        NvmeIdNs *id_ns = &ns->id_ns;

        id_ns->nsfeat = 0;

        id_ns->nlbaf = 0;

        id_ns->flbas = 0;

        id_ns->mc = 0;

        id_ns->dpc = 0;

        id_ns->dps = 0;

        id_ns->lbaf[0].ds = BDRV_SECTOR_BITS;

        id_ns->ncap  = id_ns->nuse = id_ns->nsze =

            cpu_to_le64(n->ns_size >>

                id_ns->lbaf[NVME_ID_NS_FLBAS_INDEX(ns->id_ns.flbas)].ds);

    }

    return 0;

}

