                case 0:

                    gen_op_fnstsw_EAX();

                    break;

                default:

                    goto illegal_op;

                }

                break;

            case 0x3d: /* fucomip */

                if (s->cc_op != CC_OP_DYNAMIC)

                    gen_op_set_cc_op(s->cc_op);

                gen_op_fmov_FT0_STN(opreg);

                gen_op_fucomi_ST0_FT0();

                gen_op_fpop();

                s->cc_op = CC_OP_EFLAGS;

                break;

            case 0x3e: /* fcomip */

