            gen_movs(s, ot);

        }

        break;



    case 0xaa: /* stosS */

    case 0xab:

        if ((b & 1) == 0)

            ot = OT_BYTE;

        else

            ot = dflag ? OT_LONG : OT_WORD;



        if (prefixes & (PREFIX_REPZ | PREFIX_REPNZ)) {

