    case 0x9d: /* popf */

        if (s->vm86 && s->iopl != 3) {

            gen_exception(s, EXCP0D_GPF, pc_start - s->cs_base);

        } else {

            gen_pop_T0(s);

            if (s->cpl == 0) {

                if (s->dflag) {

                    gen_op_movl_eflags_T0_cpl0();

                } else {

                    gen_op_movw_eflags_T0_cpl0();

                }

            } else {

                if (s->cpl <= s->iopl) {

                    if (s->dflag) {

                        gen_op_movl_eflags_T0_io();

                    } else {

                        gen_op_movw_eflags_T0_io();

                    }

                } else {

                    if (s->dflag) {

                        gen_op_movl_eflags_T0();

                    } else {

                        gen_op_movw_eflags_T0();

                    }

                }

