static int mm_decode_inter(MmContext * s, int half_horiz, int half_vert)

{

    int data_off = bytestream2_get_le16(&s->gb), y;

    GetByteContext data_ptr;



    if (bytestream2_get_bytes_left(&s->gb) < data_off)

        return AVERROR_INVALIDDATA;



    bytestream2_init(&data_ptr, s->gb.buffer + data_off, bytestream2_get_bytes_left(&s->gb) - data_off);

    while (s->gb.buffer < data_ptr.buffer_start) {

        int i, j;

        int length = bytestream2_get_byte(&s->gb);

        int x = bytestream2_get_byte(&s->gb) + ((length & 0x80) << 1);

        length &= 0x7F;



        if (length==0) {

            y += x;

            continue;

        }



        if (y + half_vert >= s->avctx->height)

            return 0;



        for(i=0; i<length; i++) {

            int replace_array = bytestream2_get_byte(&s->gb);

            for(j=0; j<8; j++) {

                int replace = (replace_array >> (7-j)) & 1;

                if (replace) {

                    int color = bytestream2_get_byte(&data_ptr);

                    s->frame.data[0][y*s->frame.linesize[0] + x] = color;

                    if (half_horiz)

                        s->frame.data[0][y*s->frame.linesize[0] + x + 1] = color;

                    if (half_vert) {

                        s->frame.data[0][(y+1)*s->frame.linesize[0] + x] = color;

                        if (half_horiz)

                            s->frame.data[0][(y+1)*s->frame.linesize[0] + x + 1] = color;

                    }

                }

                x += 1 + half_horiz;

            }

        }



        y += 1 + half_vert;

    }



    return 0;

}

static int ogg_read_header(AVFormatContext *s)

{

    struct ogg *ogg = s->priv_data;

    int ret, i;



    ogg->curidx = -1;



    //linear headers seek from start

    do {

        ret = ogg_packet(s, NULL, NULL, NULL, NULL);

        if (ret < 0) {

            ogg_read_close(s);

            return ret;

        }

    } while (!ogg->headers);

    av_log(s, AV_LOG_TRACE, "found headers\n");



    for (i = 0; i < ogg->nstreams; i++) {

        struct ogg_stream *os = ogg->streams + i;



        if (ogg->streams[i].header < 0) {

            av_log(s, AV_LOG_ERROR, "Header parsing failed for stream %d\n", i);

            ogg->streams[i].codec = NULL;


        } else if (os->codec && os->nb_header < os->codec->nb_header) {

            av_log(s, AV_LOG_WARNING,

                   "Headers mismatch for stream %d: "

                   "expected %d received %d.\n",

                   i, os->codec->nb_header, os->nb_header);

            if (s->error_recognition & AV_EF_EXPLODE)

                return AVERROR_INVALIDDATA;

        }

        if (os->start_granule != OGG_NOGRANULE_VALUE)

            os->lastpts = s->streams[i]->start_time =

                ogg_gptopts(s, i, os->start_granule, NULL);

    }



    //linear granulepos seek from end

    ret = ogg_get_length(s);

    if (ret < 0) {

        ogg_read_close(s);

        return ret;

    }



    return 0;

}

static inline uint8_t *ram_chunk_end(const RDMALocalBlock *rdma_ram_block,

                                     uint64_t i)

{

    uint8_t *result = ram_chunk_start(rdma_ram_block, i) +

                                         (1UL << RDMA_REG_CHUNK_SHIFT);



    if (result > (rdma_ram_block->local_host_addr + rdma_ram_block->length)) {

        result = rdma_ram_block->local_host_addr + rdma_ram_block->length;

    }



    return result;

}

static av_always_inline void hyscale(SwsContext *c, int16_t *dst, int dstWidth,

                                     const uint8_t *src_in[4], int srcW, int xInc,

                                     const int16_t *hLumFilter,

                                     const int16_t *hLumFilterPos, int hLumFilterSize,

                                     uint8_t *formatConvBuffer,

                                     uint32_t *pal, int isAlpha)

{

    void (*toYV12)(uint8_t *, const uint8_t *, int, uint32_t *) = isAlpha ? c->alpToYV12 : c->lumToYV12;

    void (*convertRange)(int16_t *, int) = isAlpha ? NULL : c->lumConvertRange;

    const uint8_t *src = src_in[isAlpha ? 3 : 0];



    if (toYV12) {

        toYV12(formatConvBuffer, src, srcW, pal);

        src= formatConvBuffer;

    } else if (c->readLumPlanar && !isAlpha) {

        c->readLumPlanar(formatConvBuffer, src_in, srcW);

        src = formatConvBuffer;

    }



    if (!c->hyscale_fast) {

        c->hyScale(c, dst, dstWidth, src, hLumFilter, hLumFilterPos, hLumFilterSize);

    } else { // fast bilinear upscale / crap downscale

        c->hyscale_fast(c, dst, dstWidth, src, srcW, xInc);

    }



    if (convertRange)

        convertRange(dst, dstWidth);

}

