static int flic_read_packet(AVFormatContext *s,

                            AVPacket *pkt)

{

    FlicDemuxContext *flic = (FlicDemuxContext *)s->priv_data;

    ByteIOContext *pb = &s->pb;

    int packet_read = 0;

    unsigned int size;

    int magic;

    int ret = 0;

    unsigned char preamble[FLIC_PREAMBLE_SIZE];



    while (!packet_read) {



        if ((ret = get_buffer(pb, preamble, FLIC_PREAMBLE_SIZE)) !=

            FLIC_PREAMBLE_SIZE) {

            ret = AVERROR_IO;

            break;

        }



        size = LE_32(&preamble[0]);

        magic = LE_16(&preamble[4]);



        if ((magic == FLIC_CHUNK_MAGIC_1) || (magic == FLIC_CHUNK_MAGIC_2)) {

            if (av_new_packet(pkt, size)) {

                ret = AVERROR_IO;

                break;

            }

            pkt->stream_index = flic->video_stream_index;

            pkt->pts = flic->pts;

            memcpy(pkt->data, preamble, FLIC_PREAMBLE_SIZE);

            ret = get_buffer(pb, pkt->data + FLIC_PREAMBLE_SIZE, 

                size - FLIC_PREAMBLE_SIZE);

            if (ret != size - FLIC_PREAMBLE_SIZE) {

                av_free_packet(pkt);

                ret = AVERROR_IO;

            }

            flic->pts += flic->frame_pts_inc;

            packet_read = 1;

        } else {

            /* not interested in this chunk */

            url_fseek(pb, size - 6, SEEK_CUR);

        }

    }



    return ret;

}

void *qemu_ram_mmap(int fd, size_t size, size_t align, bool shared)

{

    /*

     * Note: this always allocates at least one extra page of virtual address

     * space, even if size is already aligned.

     */

    size_t total = size + align;

    void *ptr = mmap(0, total, PROT_NONE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);

    size_t offset = QEMU_ALIGN_UP((uintptr_t)ptr, align) - (uintptr_t)ptr;

    void *ptr1;



    if (ptr == MAP_FAILED) {

        return NULL;

    }



    /* Make sure align is a power of 2 */

    assert(!(align & (align - 1)));

    /* Always align to host page size */

    assert(align >= getpagesize());



    ptr1 = mmap(ptr + offset, size, PROT_READ | PROT_WRITE,

                MAP_FIXED |

                (fd == -1 ? MAP_ANONYMOUS : 0) |

                (shared ? MAP_SHARED : MAP_PRIVATE),

                fd, 0);

    if (ptr1 == MAP_FAILED) {

        munmap(ptr, total);

        return NULL;

    }



    ptr += offset;

    total -= offset;



    if (offset > 0) {

        munmap(ptr - offset, offset);

    }



    /*

     * Leave a single PROT_NONE page allocated after the RAM block, to serve as

     * a guard page guarding against potential buffer overflows.

     */

    if (total > size + getpagesize()) {

        munmap(ptr + size + getpagesize(), total - size - getpagesize());

    }



    return ptr;

}

static int mov_seek_stream(AVFormatContext *s, AVStream *st, int64_t timestamp, int flags)

{

    MOVStreamContext *sc = st->priv_data;

    int sample, time_sample;

    int i;



    sample = av_index_search_timestamp(st, timestamp, flags);

    av_log(s, AV_LOG_TRACE, "stream %d, timestamp %"PRId64", sample %d\n", st->index, timestamp, sample);

    if (sample < 0 && st->nb_index_entries && timestamp < st->index_entries[0].timestamp)

        sample = 0;

    if (sample < 0) /* not sure what to do */

        return AVERROR_INVALIDDATA;

    sc->current_sample = sample;

    av_log(s, AV_LOG_TRACE, "stream %d, found sample %d\n", st->index, sc->current_sample);

    /* adjust ctts index */

    if (sc->ctts_data) {

        time_sample = 0;

        for (i = 0; i < sc->ctts_count; i++) {

            int next = time_sample + sc->ctts_data[i].count;

            if (next > sc->current_sample) {

                sc->ctts_index = i;

                sc->ctts_sample = sc->current_sample - time_sample;

                break;

            }

            time_sample = next;

        }

    }



    /* adjust stsd index */

    time_sample = 0;

    for (i = 0; i < sc->stsc_count; i++) {

        int next = time_sample + mov_get_stsc_samples(sc, i);

        if (next > sc->current_sample) {

            sc->stsc_index = i;

            sc->stsc_sample = sc->current_sample - time_sample;

            break;

        }

        time_sample = next;

    }



    return sample;

}

