static void *circular_buffer_task_tx( void *_URLContext)

{

    URLContext *h = _URLContext;

    UDPContext *s = h->priv_data;

    int old_cancelstate;



    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, &old_cancelstate);



    for(;;) {

        int len;

        uint8_t tmp[4];



        pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, &old_cancelstate);



        av_usleep(s->packet_gap);



        pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, &old_cancelstate);



        pthread_mutex_lock(&s->mutex);



        len=av_fifo_size(s->fifo);



        while (len<4) {

            if (pthread_cond_wait(&s->cond, &s->mutex) < 0) {

                goto end;

            }

            len=av_fifo_size(s->fifo);

        }



        av_fifo_generic_peek(s->fifo, tmp, 4, NULL);

        len=AV_RL32(tmp);



        if (len>0 && av_fifo_size(s->fifo)>=len+4) {

            av_fifo_drain(s->fifo, 4); /* skip packet length */

            av_fifo_generic_read(s->fifo, h, len, do_udp_write); /* use function for write from fifo buffer */

            if (s->circular_buffer_error == len) {

                /* all ok - reset error */

                s->circular_buffer_error=0;

            }

        }



        pthread_mutex_unlock(&s->mutex);

    }



end:

    pthread_mutex_unlock(&s->mutex);

    return NULL;

}

static int parse_bootdevices(char *devices)

{

    /* We just do some generic consistency checks */

    const char *p;

    int bitmap = 0;



    for (p = devices; *p != '\0'; p++) {

        /* Allowed boot devices are:

         * a-b: floppy disk drives

         * c-f: IDE disk drives

         * g-m: machine implementation dependant drives

         * n-p: network devices

         * It's up to each machine implementation to check if the given boot

         * devices match the actual hardware implementation and firmware

         * features.

         */

        if (*p < 'a' || *p > 'p') {

            fprintf(stderr, "Invalid boot device '%c'\n", *p);

            exit(1);

        }

        if (bitmap & (1 << (*p - 'a'))) {

            fprintf(stderr, "Boot device '%c' was given twice\n", *p);

            exit(1);

        }

        bitmap |= 1 << (*p - 'a');

    }

    return bitmap;

}

GList *range_list_insert(GList *list, Range *data)

{

    GList *l, *next = NULL;

    Range *r, *nextr;



    if (!list) {

        list = g_list_insert_sorted(list, data, range_compare);

        return list;

    }



    nextr = data;

    l = list;

    while (l && l != next && nextr) {

        r = l->data;

        if (ranges_can_merge(r, nextr)) {

            range_merge(r, nextr);

            l = g_list_remove_link(l, next);

            next = g_list_next(l);

            if (next) {

                nextr = next->data;

            } else {

                nextr = NULL;

            }

        } else {

            l = g_list_next(l);

        }

    }



    if (!l) {

        list = g_list_insert_sorted(list, data, range_compare);

    }



    return list;

}

