    int resulth, resultl;

    int resdsp;



    achi = 0x05;

    acli = 0xB4CB;

    rs  = 0xFF06;

    rt  = 0xCB00;

    resulth = 0x04;

    resultl = 0x947438CB;



    __asm

        ("mthi %2, $ac1\n\t"

         "mtlo %3, $ac1\n\t"

         "maq_s.w.phr $ac1, %4, %5\n\t"

         "mfhi %0, $ac1\n\t"

