         : "=r"(acho), "=r"(aclo)

         : "r"(achi), "r"(acli), "r"(rs), "r"(rt)

        );

    assert(resulth == acho);

    assert(resultl == aclo);



    achi = 0x06;

    acli = 0xB4CB;

    rs  = 0x8000;

    rt  = 0x8000;

    resulth = 0x6;

    resultl = 0x8000b4ca;

