static int caf_write_trailer(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    AVCodecContext *enc = s->streams[0]->codec;



    if (pb->seekable) {

        CAFContext *caf = s->priv_data;

        int64_t file_size = avio_tell(pb);



        avio_seek(pb, caf->data, SEEK_SET);

        avio_wb64(pb, file_size - caf->data - 8);

        avio_seek(pb, file_size, SEEK_SET);

        if (!enc->block_align) {

            ffio_wfourcc(pb, "pakt");

            avio_wb64(pb, caf->size_entries_used + 24);

            avio_wb64(pb, caf->packets); ///< mNumberPackets

            avio_wb64(pb, caf->packets * samples_per_packet(enc->codec_id, enc->channels)); ///< mNumberValidFrames

            avio_wb32(pb, 0); ///< mPrimingFrames

            avio_wb32(pb, 0); ///< mRemainderFrames

            avio_write(pb, caf->pkt_sizes, caf->size_entries_used);

            av_freep(&caf->pkt_sizes);

            caf->size_buffer_size = 0;

        }

        avio_flush(pb);

    }

    return 0;

}

static av_always_inline void hl_decode_mb_predict_luma(H264Context *h, int mb_type, int is_h264, int simple, int transform_bypass,

                                                       int pixel_shift, int *block_offset, int linesize, uint8_t *dest_y, int p)

{

    MpegEncContext * const s = &h->s;

    void (*idct_add)(uint8_t *dst, DCTELEM *block, int stride);

    void (*idct_dc_add)(uint8_t *dst, DCTELEM *block, int stride);

    int i;

    int qscale = p == 0 ? s->qscale : h->chroma_qp[p-1];

    block_offset += 16*p;

    if(IS_INTRA4x4(mb_type)){

        if(simple || !s->encoding){

            if(IS_8x8DCT(mb_type)){

                if(transform_bypass){

                    idct_dc_add =

                    idct_add    = s->dsp.add_pixels8;

                }else{

                    idct_dc_add = h->h264dsp.h264_idct8_dc_add;

                    idct_add    = h->h264dsp.h264_idct8_add;

                }

                for(i=0; i<16; i+=4){

                    uint8_t * const ptr= dest_y + block_offset[i];

                    const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];

                    if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                        h->hpc.pred8x8l_add[dir](ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                    }else{

                        const int nnz = h->non_zero_count_cache[ scan8[i+p*16] ];

                        h->hpc.pred8x8l[ dir ](ptr, (h->topleft_samples_available<<i)&0x8000,

                                                    (h->topright_samples_available<<i)&0x4000, linesize);

                        if(nnz){

                            if(nnz == 1 && dctcoef_get(h->mb, pixel_shift, i*16+p*256))

                                idct_dc_add(ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                            else

                                idct_add   (ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                        }

                    }

                }

            }else{

                if(transform_bypass){

                    idct_dc_add =

                    idct_add    = s->dsp.add_pixels4;

                }else{

                    idct_dc_add = h->h264dsp.h264_idct_dc_add;

                    idct_add    = h->h264dsp.h264_idct_add;

                }

                for(i=0; i<16; i++){

                    uint8_t * const ptr= dest_y + block_offset[i];

                    const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];



                    if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                        h->hpc.pred4x4_add[dir](ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                    }else{

                        uint8_t *topright;

                        int nnz, tr;

                        uint64_t tr_high;

                        if(dir == DIAG_DOWN_LEFT_PRED || dir == VERT_LEFT_PRED){

                            const int topright_avail= (h->topright_samples_available<<i)&0x8000;

                            assert(s->mb_y || linesize <= block_offset[i]);

                            if(!topright_avail){

                                if (pixel_shift) {

                                    tr_high= ((uint16_t*)ptr)[3 - linesize/2]*0x0001000100010001ULL;

                                    topright= (uint8_t*) &tr_high;

                                } else {

                                    tr= ptr[3 - linesize]*0x01010101;

                                    topright= (uint8_t*) &tr;

                                }

                            }else

                                topright= ptr + (4 << pixel_shift) - linesize;

                        }else

                            topright= NULL;



                        h->hpc.pred4x4[ dir ](ptr, topright, linesize);

                        nnz = h->non_zero_count_cache[ scan8[i+p*16] ];

                        if(nnz){

                            if(is_h264){

                                if(nnz == 1 && dctcoef_get(h->mb, pixel_shift, i*16+p*256))

                                    idct_dc_add(ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                                else

                                    idct_add   (ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                            }else

                                ff_svq3_add_idct_c(ptr, h->mb + i*16+p*256, linesize, qscale, 0);

                        }

                    }

                }

            }

        }

    }else{

        h->hpc.pred16x16[ h->intra16x16_pred_mode ](dest_y , linesize);

        if(is_h264){

            if(h->non_zero_count_cache[ scan8[LUMA_DC_BLOCK_INDEX+p] ]){

                if(!transform_bypass)

                    h->h264dsp.h264_luma_dc_dequant_idct(h->mb+(p*256 << pixel_shift), h->mb_luma_dc[p], h->dequant4_coeff[p][qscale][0]);

                else{

                    static const uint8_t dc_mapping[16] = { 0*16, 1*16, 4*16, 5*16, 2*16, 3*16, 6*16, 7*16,

                                                            8*16, 9*16,12*16,13*16,10*16,11*16,14*16,15*16};

                    for(i = 0; i < 16; i++)

                        dctcoef_set(h->mb+p*256, pixel_shift, dc_mapping[i], dctcoef_get(h->mb_luma_dc[p], pixel_shift, i));

                }

            }

        }else

            ff_svq3_luma_dc_dequant_idct_c(h->mb+p*256, h->mb_luma_dc[p], qscale);

    }

}

static void *file_ram_alloc(RAMBlock *block,

                            ram_addr_t memory,

                            const char *path,

                            Error **errp)

{

    bool unlink_on_error = false;

    char *filename;

    char *sanitized_name;

    char *c;

    void *area = MAP_FAILED;

    int fd = -1;

    int64_t file_size;



    if (kvm_enabled() && !kvm_has_sync_mmu()) {

        error_setg(errp,

                   "host lacks kvm mmu notifiers, -mem-path unsupported");

        return NULL;

    }



    for (;;) {

        fd = open(path, O_RDWR);

        if (fd >= 0) {

            /* @path names an existing file, use it */

            break;

        }

        if (errno == ENOENT) {

            /* @path names a file that doesn't exist, create it */

            fd = open(path, O_RDWR | O_CREAT | O_EXCL, 0644);

            if (fd >= 0) {

                unlink_on_error = true;

                break;

            }

        } else if (errno == EISDIR) {

            /* @path names a directory, create a file there */

            /* Make name safe to use with mkstemp by replacing '/' with '_'. */

            sanitized_name = g_strdup(memory_region_name(block->mr));

            for (c = sanitized_name; *c != '\0'; c++) {

                if (*c == '/') {

                    *c = '_';

                }

            }



            filename = g_strdup_printf("%s/qemu_back_mem.%s.XXXXXX", path,

                                       sanitized_name);

            g_free(sanitized_name);



            fd = mkstemp(filename);

            if (fd >= 0) {

                unlink(filename);

                g_free(filename);

                break;

            }

            g_free(filename);

        }

        if (errno != EEXIST && errno != EINTR) {

            error_setg_errno(errp, errno,

                             "can't open backing store %s for guest RAM",

                             path);

            goto error;

        }

        /*

         * Try again on EINTR and EEXIST.  The latter happens when

         * something else creates the file between our two open().

         */

    }



    block->page_size = qemu_fd_getpagesize(fd);

    block->mr->align = block->page_size;

#if defined(__s390x__)

    if (kvm_enabled()) {

        block->mr->align = MAX(block->mr->align, QEMU_VMALLOC_ALIGN);

    }

#endif



    file_size = get_file_size(fd);



    if (memory < block->page_size) {

        error_setg(errp, "memory size 0x" RAM_ADDR_FMT " must be equal to "

                   "or larger than page size 0x%zx",

                   memory, block->page_size);

        goto error;

    }



    if (file_size > 0 && file_size < memory) {

        error_setg(errp, "backing store %s size 0x%" PRIx64

                   " does not match 'size' option 0x" RAM_ADDR_FMT,

                   path, file_size, memory);

        goto error;

    }



    memory = ROUND_UP(memory, block->page_size);



    /*

     * ftruncate is not supported by hugetlbfs in older

     * hosts, so don't bother bailing out on errors.

     * If anything goes wrong with it under other filesystems,

     * mmap will fail.

     *

     * Do not truncate the non-empty backend file to avoid corrupting

     * the existing data in the file. Disabling shrinking is not

     * enough. For example, the current vNVDIMM implementation stores

     * the guest NVDIMM labels at the end of the backend file. If the

     * backend file is later extended, QEMU will not be able to find

     * those labels. Therefore, extending the non-empty backend file

     * is disabled as well.

     */

    if (!file_size && ftruncate(fd, memory)) {

        perror("ftruncate");

    }



    area = qemu_ram_mmap(fd, memory, block->mr->align,

                         block->flags & RAM_SHARED);

    if (area == MAP_FAILED) {

        error_setg_errno(errp, errno,

                         "unable to map backing store for guest RAM");

        goto error;

    }



    if (mem_prealloc) {

        os_mem_prealloc(fd, area, memory, errp);

        if (errp && *errp) {

            goto error;

        }

    }



    block->fd = fd;

    return area;



error:

    if (area != MAP_FAILED) {

        qemu_ram_munmap(area, memory);

    }

    if (unlink_on_error) {

        unlink(path);

    }

    if (fd != -1) {

        close(fd);

    }

    return NULL;

}

void avcodec_align_dimensions(AVCodecContext *s, int *width, int *height){

    int w_align= 1;

    int h_align= 1;



    switch(s->pix_fmt){

    case PIX_FMT_YUV420P:

    case PIX_FMT_YUYV422:

    case PIX_FMT_UYVY422:

    case PIX_FMT_YUV422P:

    case PIX_FMT_YUV444P:

    case PIX_FMT_GRAY8:

    case PIX_FMT_GRAY16BE:

    case PIX_FMT_GRAY16LE:

    case PIX_FMT_YUVJ420P:

    case PIX_FMT_YUVJ422P:

    case PIX_FMT_YUVJ444P:

    case PIX_FMT_YUVA420P:

        w_align= 16; //FIXME check for non mpeg style codecs and use less alignment

        h_align= 16;



        break;

    case PIX_FMT_YUV411P:

    case PIX_FMT_UYYVYY411:

        w_align=32;

        h_align=8;

        break;

    case PIX_FMT_YUV410P:

        if(s->codec_id == CODEC_ID_SVQ1){

            w_align=64;

            h_align=64;

        }

    case PIX_FMT_RGB555:

        if(s->codec_id == CODEC_ID_RPZA){

            w_align=4;

            h_align=4;

        }

    case PIX_FMT_PAL8:

    case PIX_FMT_BGR8:

    case PIX_FMT_RGB8:

        if(s->codec_id == CODEC_ID_SMC){

            w_align=4;

            h_align=4;

        }

        break;

    case PIX_FMT_BGR24:

        if((s->codec_id == CODEC_ID_MSZH) || (s->codec_id == CODEC_ID_ZLIB)){

            w_align=4;

            h_align=4;

        }

        break;

    default:

        w_align= 1;

        h_align= 1;

        break;

    }



    *width = ALIGN(*width , w_align);

    *height= ALIGN(*height, h_align);

    if(s->codec_id == CODEC_ID_H264)

        *height+=2; // some of the optimized chroma MC reads one line too much

}

int ff_dca_xll_filter_frame(DCAXllDecoder *s, AVFrame *frame)

{

    AVCodecContext *avctx = s->avctx;

    DCAContext *dca = avctx->priv_data;

    DCAExssAsset *asset = &dca->exss.assets[0];

    DCAXllChSet *p = &s->chset[0], *c;

    enum AVMatrixEncoding matrix_encoding = AV_MATRIX_ENCODING_NONE;

    int i, j, k, ret, shift, nsamples, request_mask;

    int ch_remap[DCA_SPEAKER_COUNT];



    // Force lossy downmixed output during recovery

    if (dca->packet & DCA_PACKET_RECOVERY) {

        for (i = 0, c = s->chset; i < s->nchsets; i++, c++) {

            if (i < s->nactivechsets)

                force_lossy_output(s, c);



            if (!c->primary_chset)

                c->dmix_embedded = 0;

        }



        s->scalable_lsbs = 0;

        s->fixed_lsb_width = 0;

    }



    // Filter frequency bands for active channel sets

    s->output_mask = 0;

    for (i = 0, c = s->chset; i < s->nactivechsets; i++, c++) {

        chs_filter_band_data(s, c, 0);



        if (c->residual_encode != (1 << c->nchannels) - 1

            && (ret = combine_residual_frame(s, c)) < 0)

            return ret;



        if (s->scalable_lsbs)

            chs_assemble_msbs_lsbs(s, c, 0);



        if (c->nfreqbands > 1) {

            chs_filter_band_data(s, c, 1);

            chs_assemble_msbs_lsbs(s, c, 1);

        }



        s->output_mask |= c->ch_mask;

    }



    // Undo hierarchial downmix and/or apply scaling

    for (i = 1, c = &s->chset[1]; i < s->nchsets; i++, c++) {

        if (!is_hier_dmix_chset(c))

            continue;



        if (i >= s->nactivechsets) {

            for (j = 0; j < c->nfreqbands; j++)

                if (c->bands[j].dmix_embedded)

                    scale_down_mix(s, c, j);

            break;

        }



        for (j = 0; j < c->nfreqbands; j++)

            if (c->bands[j].dmix_embedded)

                undo_down_mix(s, c, j);

    }



    // Assemble frequency bands for active channel sets

    if (s->nfreqbands > 1) {

        for (i = 0; i < s->nactivechsets; i++)

            if ((ret = chs_assemble_freq_bands(s, &s->chset[i])) < 0)

                return ret;

    }



    // Normalize to regular 5.1 layout if downmixing

    if (dca->request_channel_layout) {

        if (s->output_mask & DCA_SPEAKER_MASK_Lss) {

            s->output_samples[DCA_SPEAKER_Ls] = s->output_samples[DCA_SPEAKER_Lss];

            s->output_mask = (s->output_mask & ~DCA_SPEAKER_MASK_Lss) | DCA_SPEAKER_MASK_Ls;

        }

        if (s->output_mask & DCA_SPEAKER_MASK_Rss) {

            s->output_samples[DCA_SPEAKER_Rs] = s->output_samples[DCA_SPEAKER_Rss];

            s->output_mask = (s->output_mask & ~DCA_SPEAKER_MASK_Rss) | DCA_SPEAKER_MASK_Rs;

        }

    }



    // Handle downmixing to stereo request

    if (dca->request_channel_layout == DCA_SPEAKER_LAYOUT_STEREO

        && DCA_HAS_STEREO(s->output_mask) && p->dmix_embedded

        && (p->dmix_type == DCA_DMIX_TYPE_LoRo ||

            p->dmix_type == DCA_DMIX_TYPE_LtRt))

        request_mask = DCA_SPEAKER_LAYOUT_STEREO;

    else

        request_mask = s->output_mask;

    if (!ff_dca_set_channel_layout(avctx, ch_remap, request_mask))

        return AVERROR(EINVAL);



    avctx->sample_rate = p->freq << (s->nfreqbands - 1);



    switch (p->storage_bit_res) {

    case 16:

        avctx->sample_fmt = AV_SAMPLE_FMT_S16P;

        shift = 16 - p->pcm_bit_res;

        break;

    case 20:

    case 24:

        avctx->sample_fmt = AV_SAMPLE_FMT_S32P;

        shift = 24 - p->pcm_bit_res;

        break;

    default:

        return AVERROR(EINVAL);

    }



    avctx->bits_per_raw_sample = p->storage_bit_res;

    avctx->profile = FF_PROFILE_DTS_HD_MA;

    avctx->bit_rate = 0;



    frame->nb_samples = nsamples = s->nframesamples << (s->nfreqbands - 1);

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;



    // Downmix primary channel set to stereo

    if (request_mask != s->output_mask) {

        ff_dca_downmix_to_stereo_fixed(s->dcadsp, s->output_samples,

                                       p->dmix_coeff, nsamples,

                                       s->output_mask);

    }



    for (i = 0; i < avctx->channels; i++) {

        int32_t *samples = s->output_samples[ch_remap[i]];

        if (frame->format == AV_SAMPLE_FMT_S16P) {

            int16_t *plane = (int16_t *)frame->extended_data[i];

            for (k = 0; k < nsamples; k++)

                plane[k] = av_clip_int16(samples[k] * (1 << shift));

        } else {

            int32_t *plane = (int32_t *)frame->extended_data[i];

            for (k = 0; k < nsamples; k++)

                plane[k] = clip23(samples[k] * (1 << shift)) * (1 << 8);

        }

    }



    if (!asset->one_to_one_map_ch_to_spkr) {

        if (asset->representation_type == DCA_REPR_TYPE_LtRt)

            matrix_encoding = AV_MATRIX_ENCODING_DOLBY;

        else if (asset->representation_type == DCA_REPR_TYPE_LhRh)

            matrix_encoding = AV_MATRIX_ENCODING_DOLBYHEADPHONE;

    } else if (request_mask != s->output_mask && p->dmix_type == DCA_DMIX_TYPE_LtRt) {

        matrix_encoding = AV_MATRIX_ENCODING_DOLBY;

    }

    if ((ret = ff_side_data_update_matrix_encoding(frame, matrix_encoding)) < 0)

        return ret;



    return 0;

}

void HELPER(simcall)(CPUXtensaState *env)

{

    uint32_t *regs = env->regs;



    switch (regs[2]) {

    case TARGET_SYS_exit:

        qemu_log("exit(%d) simcall\n", regs[3]);

        exit(regs[3]);

        break;



    case TARGET_SYS_read:

    case TARGET_SYS_write:

        {

            bool is_write = regs[2] == TARGET_SYS_write;

            uint32_t fd = regs[3];

            uint32_t vaddr = regs[4];

            uint32_t len = regs[5];



            while (len > 0) {

                target_phys_addr_t paddr =

                    cpu_get_phys_page_debug(env, vaddr);

                uint32_t page_left =

                    TARGET_PAGE_SIZE - (vaddr & (TARGET_PAGE_SIZE - 1));

                uint32_t io_sz = page_left < len ? page_left : len;

                target_phys_addr_t sz = io_sz;

                void *buf = cpu_physical_memory_map(paddr, &sz, is_write);



                if (buf) {

                    vaddr += io_sz;

                    len -= io_sz;

                    regs[2] = is_write ?

                        write(fd, buf, io_sz) :

                        read(fd, buf, io_sz);

                    regs[3] = errno;

                    cpu_physical_memory_unmap(buf, sz, is_write, sz);

                    if (regs[2] == -1) {

                        break;

                    }

                } else {


                    regs[3] = EINVAL;

                    break;

                }

            }

        }

        break;



    case TARGET_SYS_open:

        {

            char name[1024];

            int rc;

            int i;



            for (i = 0; i < ARRAY_SIZE(name); ++i) {

                rc = cpu_memory_rw_debug(

                        env, regs[3] + i, (uint8_t *)name + i, 1, 0);

                if (rc != 0 || name[i] == 0) {

                    break;

                }

            }



            if (rc == 0 && i < ARRAY_SIZE(name)) {

                regs[2] = open(name, regs[4], regs[5]);

                regs[3] = errno;

            } else {


                regs[3] = EINVAL;

            }

        }

        break;



    case TARGET_SYS_close:

        if (regs[3] < 3) {

            regs[2] = regs[3] = 0;

        } else {

            regs[2] = close(regs[3]);

            regs[3] = errno;

        }

        break;



    case TARGET_SYS_lseek:

        regs[2] = lseek(regs[3], (off_t)(int32_t)regs[4], regs[5]);

        regs[3] = errno;

        break;



    case TARGET_SYS_select_one:

        {

            uint32_t fd = regs[3];

            uint32_t rq = regs[4];

            uint32_t target_tv = regs[5];

            uint32_t target_tvv[2];



            struct timeval tv = {0};

            fd_set fdset;



            FD_ZERO(&fdset);

            FD_SET(fd, &fdset);



            if (target_tv) {

                cpu_memory_rw_debug(env, target_tv,

                        (uint8_t *)target_tvv, sizeof(target_tvv), 0);

                tv.tv_sec = (int32_t)tswap32(target_tvv[0]);

                tv.tv_usec = (int32_t)tswap32(target_tvv[1]);

            }

            regs[2] = select(fd + 1,

                    rq == SELECT_ONE_READ   ? &fdset : NULL,

                    rq == SELECT_ONE_WRITE  ? &fdset : NULL,

                    rq == SELECT_ONE_EXCEPT ? &fdset : NULL,

                    target_tv ? &tv : NULL);

            regs[3] = errno;

        }

        break;



    case TARGET_SYS_argc:

        regs[2] = 1;

        regs[3] = 0;

        break;



    case TARGET_SYS_argv_sz:

        regs[2] = 128;

        regs[3] = 0;

        break;



    case TARGET_SYS_argv:

        {

            struct Argv {

                uint32_t argptr[2];

                char text[120];

            } argv = {

                {0, 0},

                "test"

            };



            argv.argptr[0] = tswap32(regs[3] + offsetof(struct Argv, text));

            cpu_memory_rw_debug(

                    env, regs[3], (uint8_t *)&argv, sizeof(argv), 1);

        }

        break;



    case TARGET_SYS_memset:

        {

            uint32_t base = regs[3];

            uint32_t sz = regs[5];



            while (sz) {

                target_phys_addr_t len = sz;

                void *buf = cpu_physical_memory_map(base, &len, 1);



                if (buf && len) {

                    memset(buf, regs[4], len);

                    cpu_physical_memory_unmap(buf, len, 1, len);

                } else {

                    len = 1;

                }

                base += len;

                sz -= len;

            }

            regs[2] = regs[3];

            regs[3] = 0;

        }

        break;



    default:

        qemu_log("%s(%d): not implemented\n", __func__, regs[2]);



        break;

    }

}

static void virtio_net_vhost_status(VirtIONet *n, uint8_t status)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(n);

    NetClientState *nc = qemu_get_queue(n->nic);

    int queues = n->multiqueue ? n->max_queues : 1;



    if (!get_vhost_net(nc->peer)) {

        return;

    }



    if ((virtio_net_started(n, status) && !nc->peer->link_down) ==

        !!n->vhost_started) {

        return;

    }

    if (!n->vhost_started) {

        int r, i;



        if (!vhost_net_query(get_vhost_net(nc->peer), vdev)) {

            return;

        }



        /* Any packets outstanding? Purge them to avoid touching rings

         * when vhost is running.

         */

        for (i = 0;  i < queues; i++) {

            NetClientState *qnc = qemu_get_subqueue(n->nic, i);



            /* Purge both directions: TX and RX. */

            qemu_net_queue_purge(qnc->peer->incoming_queue, qnc);

            qemu_net_queue_purge(qnc->incoming_queue, qnc->peer);

        }



        n->vhost_started = 1;

        r = vhost_net_start(vdev, n->nic->ncs, queues);

        if (r < 0) {

            error_report("unable to start vhost net: %d: "

                         "falling back on userspace virtio", -r);

            n->vhost_started = 0;

        }

    } else {

        vhost_net_stop(vdev, n->nic->ncs, queues);

        n->vhost_started = 0;

    }

}

static int handle_update_file_cred(int dirfd, const char *name, FsCred *credp)

{

    int fd, ret;

    fd = openat(dirfd, name, O_NONBLOCK | O_NOFOLLOW);

    if (fd < 0) {

        return fd;

    }

    ret = fchmod(fd, credp->fc_mode & 07777);

    if (ret < 0) {

        goto err_out;

    }

    ret = fchownat(fd, "", credp->fc_uid, credp->fc_gid, AT_EMPTY_PATH);

err_out:

    close(fd);

    return ret;

}

