static av_always_inline void predict_slice_buffered(SnowContext *s, slice_buffer * sb, IDWTELEM * old_buffer, int plane_index, int add, int mb_y){

    Plane *p= &s->plane[plane_index];

    const int mb_w= s->b_width  << s->block_max_depth;

    const int mb_h= s->b_height << s->block_max_depth;

    int x, y, mb_x;

    int block_size = MB_SIZE >> s->block_max_depth;

    int block_w    = plane_index ? block_size>>s->chroma_h_shift : block_size;

    int block_h    = plane_index ? block_size>>s->chroma_v_shift : block_size;

    const uint8_t *obmc  = plane_index ? ff_obmc_tab[s->block_max_depth+s->chroma_h_shift] : ff_obmc_tab[s->block_max_depth];

    int obmc_stride= plane_index ? (2*block_size)>>s->chroma_h_shift : 2*block_size;

    int ref_stride= s->current_picture->linesize[plane_index];

    uint8_t *dst8= s->current_picture->data[plane_index];

    int w= p->width;

    int h= p->height;



    if(s->keyframe || (s->avctx->debug&512)){

        if(mb_y==mb_h)

            return;



        if(add){

            for(y=block_h*mb_y; y<FFMIN(h,block_h*(mb_y+1)); y++){

//                DWTELEM * line = slice_buffer_get_line(sb, y);

                IDWTELEM * line = sb->line[y];

                for(x=0; x<w; x++){

//                    int v= buf[x + y*w] + (128<<FRAC_BITS) + (1<<(FRAC_BITS-1));

                    int v= line[x] + (128<<FRAC_BITS) + (1<<(FRAC_BITS-1));

                    v >>= FRAC_BITS;

                    if(v&(~255)) v= ~(v>>31);

                    dst8[x + y*ref_stride]= v;

                }

            }

        }else{

            for(y=block_h*mb_y; y<FFMIN(h,block_h*(mb_y+1)); y++){

//                DWTELEM * line = slice_buffer_get_line(sb, y);

                IDWTELEM * line = sb->line[y];

                for(x=0; x<w; x++){

                    line[x] -= 128 << FRAC_BITS;

//                    buf[x + y*w]-= 128<<FRAC_BITS;

                }

            }

        }



        return;

    }



    for(mb_x=0; mb_x<=mb_w; mb_x++){

        add_yblock(s, 1, sb, old_buffer, dst8, obmc,

                   block_w*mb_x - block_w/2,

                   block_h*mb_y - block_h/2,

                   block_w, block_h,

                   w, h,

                   w, ref_stride, obmc_stride,

                   mb_x - 1, mb_y - 1,

                   add, 0, plane_index);

    }



    if(s->avmv && mb_y < mb_h && plane_index == 0)

        for(mb_x=0; mb_x<mb_w; mb_x++){

            AVMotionVector *avmv = s->avmv + (s->avmv_index++);

            const int b_width = s->b_width  << s->block_max_depth;

            const int b_stride= b_width;

            BlockNode *bn= &s->block[mb_x + mb_y*b_stride];



            if (bn->type)

                continue;



            avmv->w = block_w;

            avmv->h = block_h;

            avmv->dst_x = block_w*mb_x - block_w/2;

            avmv->dst_y = block_h*mb_y - block_h/2;

            avmv->src_x = avmv->dst_x + (bn->mx * s->mv_scale)/8;

            avmv->src_y = avmv->dst_y + (bn->my * s->mv_scale)/8;

            avmv->source= -1 - bn->ref;

            avmv->flags = 0;

        }

}

static void rtsp_cmd_setup(HTTPContext *c, const char *url,

                           RTSPHeader *h)

{

    FFStream *stream;

    int stream_index, port;

    char buf[1024];

    char path1[1024];

    const char *path;

    HTTPContext *rtp_c;

    RTSPTransportField *th;

    struct sockaddr_in dest_addr;

    RTSPActionServerSetup setup;



    /* find which url is asked */

    url_split(NULL, 0, NULL, 0, NULL, 0, NULL, path1, sizeof(path1), url);

    path = path1;

    if (*path == '/')

        path++;



    /* now check each stream */

    for(stream = first_stream; stream != NULL; stream = stream->next) {

        if (!stream->is_feed && !strcmp(stream->fmt->name, "rtp")) {

            /* accept aggregate filenames only if single stream */

            if (!strcmp(path, stream->filename)) {

                if (stream->nb_streams != 1) {

                    rtsp_reply_error(c, RTSP_STATUS_AGGREGATE);

                    return;

                }

                stream_index = 0;

                goto found;

            }



            for(stream_index = 0; stream_index < stream->nb_streams;

                stream_index++) {

                snprintf(buf, sizeof(buf), "%s/streamid=%d",

                         stream->filename, stream_index);

                if (!strcmp(path, buf))

                    goto found;

            }

        }

    }

    /* no stream found */

    rtsp_reply_error(c, RTSP_STATUS_SERVICE); /* XXX: right error ? */

    return;

 found:



    /* generate session id if needed */

    if (h->session_id[0] == '\0')

        snprintf(h->session_id, sizeof(h->session_id), "%08x%08x",

                 av_random(&random_state), av_random(&random_state));



    /* find rtp session, and create it if none found */

    rtp_c = find_rtp_session(h->session_id);

    if (!rtp_c) {

        /* always prefer UDP */

        th = find_transport(h, RTSP_PROTOCOL_RTP_UDP);

        if (!th) {

            th = find_transport(h, RTSP_PROTOCOL_RTP_TCP);

            if (!th) {

                rtsp_reply_error(c, RTSP_STATUS_TRANSPORT);

                return;

            }

        }



        rtp_c = rtp_new_connection(&c->from_addr, stream, h->session_id,

                                   th->protocol);

        if (!rtp_c) {

            rtsp_reply_error(c, RTSP_STATUS_BANDWIDTH);

            return;

        }



        /* open input stream */

        if (open_input_stream(rtp_c, "") < 0) {

            rtsp_reply_error(c, RTSP_STATUS_INTERNAL);

            return;

        }

    }



    /* test if stream is OK (test needed because several SETUP needs

       to be done for a given file) */

    if (rtp_c->stream != stream) {

        rtsp_reply_error(c, RTSP_STATUS_SERVICE);

        return;

    }



    /* test if stream is already set up */

    if (rtp_c->rtp_ctx[stream_index]) {

        rtsp_reply_error(c, RTSP_STATUS_STATE);

        return;

    }



    /* check transport */

    th = find_transport(h, rtp_c->rtp_protocol);

    if (!th || (th->protocol == RTSP_PROTOCOL_RTP_UDP &&

                th->client_port_min <= 0)) {

        rtsp_reply_error(c, RTSP_STATUS_TRANSPORT);

        return;

    }



    /* setup default options */

    setup.transport_option[0] = '\0';

    dest_addr = rtp_c->from_addr;

    dest_addr.sin_port = htons(th->client_port_min);



    /* setup stream */

    if (rtp_new_av_stream(rtp_c, stream_index, &dest_addr, c) < 0) {

        rtsp_reply_error(c, RTSP_STATUS_TRANSPORT);

        return;

    }



    /* now everything is OK, so we can send the connection parameters */

    rtsp_reply_header(c, RTSP_STATUS_OK);

    /* session ID */

    url_fprintf(c->pb, "Session: %s\r\n", rtp_c->session_id);



    switch(rtp_c->rtp_protocol) {

    case RTSP_PROTOCOL_RTP_UDP:

        port = rtp_get_local_port(rtp_c->rtp_handles[stream_index]);

        url_fprintf(c->pb, "Transport: RTP/AVP/UDP;unicast;"

                    "client_port=%d-%d;server_port=%d-%d",

                    th->client_port_min, th->client_port_min + 1,

                    port, port + 1);

        break;

    case RTSP_PROTOCOL_RTP_TCP:

        url_fprintf(c->pb, "Transport: RTP/AVP/TCP;interleaved=%d-%d",

                    stream_index * 2, stream_index * 2 + 1);

        break;

    default:

        break;

    }

    if (setup.transport_option[0] != '\0')

        url_fprintf(c->pb, ";%s", setup.transport_option);

    url_fprintf(c->pb, "\r\n");





    url_fprintf(c->pb, "\r\n");

}

static void decompress_data_with_multi_threads(QEMUFile *f,

                                               void *host, int len)

{

    int idx, thread_count;



    thread_count = migrate_decompress_threads();

    while (true) {

        for (idx = 0; idx < thread_count; idx++) {

            if (!decomp_param[idx].start) {

                qemu_get_buffer(f, decomp_param[idx].compbuf, len);

                decomp_param[idx].des = host;

                decomp_param[idx].len = len;

                start_decompression(&decomp_param[idx]);

                break;

            }

        }

        if (idx < thread_count) {

            break;

        }

    }

}

