            break;

        case 5:

            mantissa = b5_mantissas[get_bits(gbc, 4)];

            break;

        default: /* 6 to 15 */

            /* Shift mantissa and sign-extend it. */





            mantissa = get_sbits(gbc, quantization_tab[bap]);

            mantissa <<= 24 - quantization_tab[bap];

            break;


