uint32_t kvm_arch_get_supported_cpuid(CPUState *env, uint32_t function,

                                      uint32_t index, int reg)

{

    struct kvm_cpuid2 *cpuid;

    int i, max;

    uint32_t ret = 0;

    uint32_t cpuid_1_edx;



    if (!kvm_check_extension(env->kvm_state, KVM_CAP_EXT_CPUID)) {

        return -1U;

    }



    max = 1;

    while ((cpuid = try_get_cpuid(env->kvm_state, max)) == NULL) {

        max *= 2;

    }



    for (i = 0; i < cpuid->nent; ++i) {

        if (cpuid->entries[i].function == function &&

            cpuid->entries[i].index == index) {

            switch (reg) {

            case R_EAX:

                ret = cpuid->entries[i].eax;

                break;

            case R_EBX:

                ret = cpuid->entries[i].ebx;

                break;

            case R_ECX:

                ret = cpuid->entries[i].ecx;

                break;

            case R_EDX:

                ret = cpuid->entries[i].edx;

                switch (function) {

                case 1:

                    /* KVM before 2.6.30 misreports the following features */

                    ret |= CPUID_MTRR | CPUID_PAT | CPUID_MCE | CPUID_MCA;

                    break;

                case 0x80000001:

                    /* On Intel, kvm returns cpuid according to the Intel spec,

                     * so add missing bits according to the AMD spec:

                     */

                    cpuid_1_edx = kvm_arch_get_supported_cpuid(env, 1, 0, R_EDX);

                    ret |= cpuid_1_edx & 0x183f7ff;

                    break;

                }

                break;

            }

        }

    }



    qemu_free(cpuid);



    return ret;

}

int64_t qcow2_alloc_bytes(BlockDriverState *bs, int size)

{

    BDRVQcowState *s = bs->opaque;

    int64_t offset;

    size_t free_in_cluster;

    int ret;



    BLKDBG_EVENT(bs->file, BLKDBG_CLUSTER_ALLOC_BYTES);

    assert(size > 0 && size <= s->cluster_size);

    assert(!s->free_byte_offset || offset_into_cluster(s, s->free_byte_offset));



    offset = s->free_byte_offset;



    if (offset) {

        uint64_t refcount;

        ret = qcow2_get_refcount(bs, offset >> s->cluster_bits, &refcount);

        if (ret < 0) {

            return ret;

        }



        if (refcount == s->refcount_max) {

            offset = 0;

        }

    }



    free_in_cluster = s->cluster_size - offset_into_cluster(s, offset);

    if (!offset || free_in_cluster < size) {

        int64_t new_cluster = alloc_clusters_noref(bs, s->cluster_size);

        if (new_cluster < 0) {

            return new_cluster;

        }



        if (!offset || ROUND_UP(offset, s->cluster_size) != new_cluster) {

            offset = new_cluster;

        }

    }



    assert(offset);

    ret = update_refcount(bs, offset, size, 1, false, QCOW2_DISCARD_NEVER);

    if (ret < 0) {

        return ret;

    }



    /* The cluster refcount was incremented; refcount blocks must be flushed

     * before the caller's L2 table updates. */

    qcow2_cache_set_dependency(bs, s->l2_table_cache, s->refcount_block_cache);



    s->free_byte_offset = offset + size;

    if (!offset_into_cluster(s, s->free_byte_offset)) {

        s->free_byte_offset = 0;

    }



    return offset;

}

