static int ogg_packet(AVFormatContext *s, int *str, int *dstart, int *dsize,

                      int64_t *fpos)

{

    struct ogg *ogg = s->priv_data;

    int idx, i, ret;

    struct ogg_stream *os;

    int complete = 0;

    int segp = 0, psize = 0;



    av_dlog(s, "ogg_packet: curidx=%i\n", ogg->curidx);



    do{

        idx = ogg->curidx;



        while (idx < 0){

            ret = ogg_read_page(s, &idx);

            if (ret < 0)

                return ret;

        }



        os = ogg->streams + idx;



        av_dlog(s, "ogg_packet: idx=%d pstart=%d psize=%d segp=%d nsegs=%d\n",

                idx, os->pstart, os->psize, os->segp, os->nsegs);



        if (!os->codec){

            if (os->header < 0){

                os->codec = ogg_find_codec (os->buf, os->bufpos);

                if (!os->codec){

                    av_log(s, AV_LOG_WARNING, "Codec not found\n");

                    os->header = 0;

                    return 0;

                }

            }else{

                return 0;

            }

        }



        segp = os->segp;

        psize = os->psize;



        while (os->segp < os->nsegs){

            int ss = os->segments[os->segp++];

            os->psize += ss;

            if (ss < 255){

                complete = 1;

                break;

            }

        }



        if (!complete && os->segp == os->nsegs){

            ogg->curidx = -1;

            os->incomplete = 1;

        }

    }while (!complete);





    if (os->granule == -1)

        av_log(s, AV_LOG_WARNING, "Page at %"PRId64" is missing granule\n", os->page_pos);



    ogg->curidx = idx;

    os->incomplete = 0;



    if (os->header) {

        os->header = os->codec->header (s, idx);

        if (!os->header){

            os->segp = segp;

            os->psize = psize;



            // We have reached the first non-header packet in this stream.

            // Unfortunately more header packets may still follow for others,

            // but if we continue with header parsing we may lose data packets.

            ogg->headers = 1;



            // Update the header state for all streams and

            // compute the data_offset.

            if (!s->data_offset)

                s->data_offset = os->sync_pos;

            for (i = 0; i < ogg->nstreams; i++) {

                struct ogg_stream *cur_os = ogg->streams + i;



                // if we have a partial non-header packet, its start is

                // obviously at or after the data start

                if (cur_os->incomplete)

                    s->data_offset = FFMIN(s->data_offset, cur_os->sync_pos);

            }

        }else{

            os->pstart += os->psize;

            os->psize = 0;

        }

    } else {

        os->pflags = 0;

        os->pduration = 0;

        if (os->codec && os->codec->packet)

            os->codec->packet (s, idx);

        if (str)

            *str = idx;

        if (dstart)

            *dstart = os->pstart;

        if (dsize)

            *dsize = os->psize;

        if (fpos)

            *fpos = os->sync_pos;

        os->pstart += os->psize;

        os->psize = 0;

        if(os->pstart == os->bufpos)

            os->bufpos = os->pstart = 0;

        os->sync_pos = os->page_pos;

    }



    // determine whether there are more complete packets in this page

    // if not, the page's granule will apply to this packet

    os->page_end = 1;

    for (i = os->segp; i < os->nsegs; i++)

        if (os->segments[i] < 255) {

            os->page_end = 0;

            break;

        }



    if (os->segp == os->nsegs)

        ogg->curidx = -1;



    return 0;

}

static int encode_init(AVCodecContext * avctx){

    WMACodecContext *s = avctx->priv_data;

    int i, flags1, flags2;

    uint8_t *extradata;



    s->avctx = avctx;



    if(avctx->channels > MAX_CHANNELS) {

        av_log(avctx, AV_LOG_ERROR, "too many channels: got %i, need %i or fewer",

               avctx->channels, MAX_CHANNELS);

        return AVERROR(EINVAL);

    }



    if(avctx->bit_rate < 24*1000) {

        av_log(avctx, AV_LOG_ERROR, "bitrate too low: got %i, need 24000 or higher\n",

               avctx->bit_rate);

        return AVERROR(EINVAL);

    }



    /* extract flag infos */

    flags1 = 0;

    flags2 = 1;

    if (avctx->codec->id == CODEC_ID_WMAV1) {

        extradata= av_malloc(4);

        avctx->extradata_size= 4;

        AV_WL16(extradata, flags1);

        AV_WL16(extradata+2, flags2);

    } else if (avctx->codec->id == CODEC_ID_WMAV2) {

        extradata= av_mallocz(10);

        avctx->extradata_size= 10;

        AV_WL32(extradata, flags1);

        AV_WL16(extradata+4, flags2);

    }else

        assert(0);

    avctx->extradata= extradata;

    s->use_exp_vlc = flags2 & 0x0001;

    s->use_bit_reservoir = flags2 & 0x0002;

    s->use_variable_block_len = flags2 & 0x0004;



    ff_wma_init(avctx, flags2);



    /* init MDCT */

    for(i = 0; i < s->nb_block_sizes; i++)

        ff_mdct_init(&s->mdct_ctx[i], s->frame_len_bits - i + 1, 0, 1.0);



    avctx->block_align=

    s->block_align= avctx->bit_rate*(int64_t)s->frame_len / (avctx->sample_rate*8);

//av_log(NULL, AV_LOG_ERROR, "%d %d %d %d\n", s->block_align, avctx->bit_rate, s->frame_len, avctx->sample_rate);

    avctx->frame_size= s->frame_len;



    return 0;

}

