static int encode_frame(AVCodecContext *avctx, AVPacket *avpkt,
                        const AVFrame *frame, int *got_packet_ptr)
{
    DCAEncContext *c = avctx->priv_data;
    const int32_t *samples;
    int ret, i;
    if ((ret = ff_alloc_packet2(avctx, avpkt, c->frame_size , 0)) < 0)
        return ret;
    samples = (const int32_t *)frame->data[0];
    subband_transform(c, samples);
    if (c->lfe_channel)
        lfe_downsample(c, samples);
    calc_masking(c, samples);
    find_peaks(c);
    assign_bits(c);
    calc_scales(c);
    quantize_all(c);
    shift_history(c, samples);
    init_put_bits(&c->pb, avpkt->data, avpkt->size);
    put_frame_header(c);
    put_primary_audio_header(c);
    for (i = 0; i < SUBFRAMES; i++)
        put_subframe(c, i);
    flush_put_bits(&c->pb);
    avpkt->pts      = frame->pts;
    avpkt->duration = ff_samples_to_time_base(avctx, frame->nb_samples);
    avpkt->size     = c->frame_size + 1;
    *got_packet_ptr = 1;
    return 0;
}

void st_set_trace_file_enabled(bool enable)

{

    if (enable == !!trace_fp) {

        return; /* no change */

    }



    /* Halt trace writeout */

    flush_trace_file(true);

    trace_writeout_enabled = false;

    flush_trace_file(true);



    if (enable) {

        static const TraceRecord header = {

            .event = HEADER_EVENT_ID,

            .timestamp_ns = HEADER_MAGIC,

            .x1 = HEADER_VERSION,

        };



        trace_fp = fopen(trace_file_name, "w");

        if (!trace_fp) {

            return;

        }



        if (fwrite(&header, sizeof header, 1, trace_fp) != 1) {

            fclose(trace_fp);

            trace_fp = NULL;

            return;

        }



        /* Resume trace writeout */

        trace_writeout_enabled = true;

        flush_trace_file(false);

    } else {

        fclose(trace_fp);

        trace_fp = NULL;

    }

}

static void client_close(NBDClient *client)

{

    if (client->closing) {

        return;

    }



    client->closing = true;



    /* Force requests to finish.  They will drop their own references,

     * then we'll close the socket and free the NBDClient.

     */

    qio_channel_shutdown(client->ioc, QIO_CHANNEL_SHUTDOWN_BOTH,

                         NULL);



    /* Also tell the client, so that they release their reference.  */

    if (client->close) {

        client->close(client);

    }

}

static const TCGTargetOpDef *tcg_target_op_def(TCGOpcode op)

{

    static const TCGTargetOpDef r = { .args_ct_str = { "r" } };

    static const TCGTargetOpDef r_r = { .args_ct_str = { "r", "r" } };

    static const TCGTargetOpDef r_L = { .args_ct_str = { "r", "L" } };

    static const TCGTargetOpDef L_L = { .args_ct_str = { "L", "L" } };

    static const TCGTargetOpDef r_ri = { .args_ct_str = { "r", "ri" } };

    static const TCGTargetOpDef r_rC = { .args_ct_str = { "r", "rC" } };

    static const TCGTargetOpDef r_rZ = { .args_ct_str = { "r", "rZ" } };

    static const TCGTargetOpDef r_r_ri = { .args_ct_str = { "r", "r", "ri" } };

    static const TCGTargetOpDef r_0_ri = { .args_ct_str = { "r", "0", "ri" } };

    static const TCGTargetOpDef r_0_rI = { .args_ct_str = { "r", "0", "rI" } };

    static const TCGTargetOpDef r_0_rJ = { .args_ct_str = { "r", "0", "rJ" } };

    static const TCGTargetOpDef r_0_rO = { .args_ct_str = { "r", "0", "rO" } };

    static const TCGTargetOpDef r_0_rX = { .args_ct_str = { "r", "0", "rX" } };



    switch (op) {

    case INDEX_op_goto_ptr:

        return &r;



    case INDEX_op_ld8u_i32:

    case INDEX_op_ld8u_i64:

    case INDEX_op_ld8s_i32:

    case INDEX_op_ld8s_i64:

    case INDEX_op_ld16u_i32:

    case INDEX_op_ld16u_i64:

    case INDEX_op_ld16s_i32:

    case INDEX_op_ld16s_i64:

    case INDEX_op_ld_i32:

    case INDEX_op_ld32u_i64:

    case INDEX_op_ld32s_i64:

    case INDEX_op_ld_i64:

    case INDEX_op_st8_i32:

    case INDEX_op_st8_i64:

    case INDEX_op_st16_i32:

    case INDEX_op_st16_i64:

    case INDEX_op_st_i32:

    case INDEX_op_st32_i64:

    case INDEX_op_st_i64:

        return &r_r;



    case INDEX_op_add_i32:

    case INDEX_op_add_i64:

        return &r_r_ri;

    case INDEX_op_sub_i32:

    case INDEX_op_sub_i64:

        return &r_0_ri;



    case INDEX_op_mul_i32:

        /* If we have the general-instruction-extensions, then we have

           MULTIPLY SINGLE IMMEDIATE with a signed 32-bit, otherwise we

           have only MULTIPLY HALFWORD IMMEDIATE, with a signed 16-bit.  */

        return (s390_facilities & FACILITY_GEN_INST_EXT ? &r_0_ri : &r_0_rI);

    case INDEX_op_mul_i64:

        return (s390_facilities & FACILITY_GEN_INST_EXT ? &r_0_rJ : &r_0_rI);



    case INDEX_op_or_i32:

    case INDEX_op_or_i64:

        return &r_0_rO;

    case INDEX_op_xor_i32:

    case INDEX_op_xor_i64:

        return &r_0_rX;

    case INDEX_op_and_i32:

    case INDEX_op_and_i64:

        return &r_0_ri;



    case INDEX_op_shl_i32:

    case INDEX_op_shr_i32:

    case INDEX_op_sar_i32:

        return &r_0_ri;



    case INDEX_op_shl_i64:

    case INDEX_op_shr_i64:

    case INDEX_op_sar_i64:

        return &r_r_ri;



    case INDEX_op_rotl_i32:

    case INDEX_op_rotl_i64:

    case INDEX_op_rotr_i32:

    case INDEX_op_rotr_i64:

        return &r_r_ri;



    case INDEX_op_brcond_i32:

        /* Without EXT_IMM, only the LOAD AND TEST insn is available.  */

        return (s390_facilities & FACILITY_EXT_IMM ? &r_ri : &r_rZ);

    case INDEX_op_brcond_i64:

        return (s390_facilities & FACILITY_EXT_IMM ? &r_rC : &r_rZ);



    case INDEX_op_bswap16_i32:

    case INDEX_op_bswap16_i64:

    case INDEX_op_bswap32_i32:

    case INDEX_op_bswap32_i64:

    case INDEX_op_bswap64_i64:

    case INDEX_op_neg_i32:

    case INDEX_op_neg_i64:

    case INDEX_op_ext8s_i32:

    case INDEX_op_ext8s_i64:

    case INDEX_op_ext8u_i32:

    case INDEX_op_ext8u_i64:

    case INDEX_op_ext16s_i32:

    case INDEX_op_ext16s_i64:

    case INDEX_op_ext16u_i32:

    case INDEX_op_ext16u_i64:

    case INDEX_op_ext32s_i64:

    case INDEX_op_ext32u_i64:

    case INDEX_op_ext_i32_i64:

    case INDEX_op_extu_i32_i64:

    case INDEX_op_extract_i32:

    case INDEX_op_extract_i64:

        return &r_r;



    case INDEX_op_clz_i64:

        return &r_r_ri;



    case INDEX_op_qemu_ld_i32:

    case INDEX_op_qemu_ld_i64:

        return &r_L;

    case INDEX_op_qemu_st_i64:

    case INDEX_op_qemu_st_i32:

        return &L_L;



    case INDEX_op_deposit_i32:

    case INDEX_op_deposit_i64:

        {

            static const TCGTargetOpDef dep

                = { .args_ct_str = { "r", "rZ", "r" } };

            return &dep;

        }

    case INDEX_op_setcond_i32:

    case INDEX_op_setcond_i64:

        {

            /* Without EXT_IMM, only the LOAD AND TEST insn is available.  */

            static const TCGTargetOpDef setc_z

                = { .args_ct_str = { "r", "r", "rZ" } };

            static const TCGTargetOpDef setc_c

                = { .args_ct_str = { "r", "r", "rC" } };

            return (s390_facilities & FACILITY_EXT_IMM ? &setc_c : &setc_z);

        }

    case INDEX_op_movcond_i32:

    case INDEX_op_movcond_i64:

        {

            /* Without EXT_IMM, only the LOAD AND TEST insn is available.  */

            static const TCGTargetOpDef movc_z

                = { .args_ct_str = { "r", "r", "rZ", "r", "0" } };

            static const TCGTargetOpDef movc_c

                = { .args_ct_str = { "r", "r", "rC", "r", "0" } };

            return (s390_facilities & FACILITY_EXT_IMM ? &movc_c : &movc_z);

        }

    case INDEX_op_div2_i32:

    case INDEX_op_div2_i64:

    case INDEX_op_divu2_i32:

    case INDEX_op_divu2_i64:

        {

            static const TCGTargetOpDef div2

                = { .args_ct_str = { "b", "a", "0", "1", "r" } };

            return &div2;

        }

    case INDEX_op_mulu2_i64:

        {

            static const TCGTargetOpDef mul2

                = { .args_ct_str = { "b", "a", "0", "r" } };

            return &mul2;

        }

    case INDEX_op_add2_i32:

    case INDEX_op_add2_i64:

    case INDEX_op_sub2_i32:

    case INDEX_op_sub2_i64:

        {

            static const TCGTargetOpDef arith2

                = { .args_ct_str = { "r", "r", "0", "1", "rA", "r" } };

            return &arith2;

        }



    default:

        break;

    }

    return NULL;

}

static void vnc_refresh(DisplayChangeListener *dcl)

{

    VncDisplay *vd = container_of(dcl, VncDisplay, dcl);

    VncState *vs, *vn;

    int has_dirty, rects = 0;



    graphic_hw_update(NULL);



    if (vnc_trylock_display(vd)) {

        update_displaychangelistener(&vd->dcl, VNC_REFRESH_INTERVAL_BASE);

        return;

    }



    has_dirty = vnc_refresh_server_surface(vd);

    vnc_unlock_display(vd);



    QTAILQ_FOREACH_SAFE(vs, &vd->clients, next, vn) {

        rects += vnc_update_client(vs, has_dirty);

        /* vs might be free()ed here */

    }



    if (QTAILQ_EMPTY(&vd->clients)) {

        update_displaychangelistener(&vd->dcl, VNC_REFRESH_INTERVAL_MAX);

        return;

    }



    if (has_dirty && rects) {

        vd->dcl.update_interval /= 2;

        if (vd->dcl.update_interval < VNC_REFRESH_INTERVAL_BASE) {

            vd->dcl.update_interval = VNC_REFRESH_INTERVAL_BASE;

        }

    } else {

        vd->dcl.update_interval += VNC_REFRESH_INTERVAL_INC;

        if (vd->dcl.update_interval > VNC_REFRESH_INTERVAL_MAX) {

            vd->dcl.update_interval = VNC_REFRESH_INTERVAL_MAX;

        }

    }

}

