static void find_compressor(char * compressor_name, int len, MOVTrack *track)

{

    AVDictionaryEntry *encoder;

    int xdcam_res =  (track->par->width == 1280 && track->par->height == 720)

                  || (track->par->width == 1440 && track->par->height == 1080)

                  || (track->par->width == 1920 && track->par->height == 1080);



    if (track->mode == MODE_MOV &&

        (encoder = av_dict_get(track->st->metadata, "encoder", NULL, 0))) {

        av_strlcpy(compressor_name, encoder->value, 32);

    } else if (track->par->codec_id == AV_CODEC_ID_MPEG2VIDEO && xdcam_res) {

        int interlaced = track->par->field_order > AV_FIELD_PROGRESSIVE;

        AVStream *st = track->st;

        int rate = av_q2d(find_fps(NULL, st));

        av_strlcatf(compressor_name, len, "XDCAM");

        if (track->par->format == AV_PIX_FMT_YUV422P) {

            av_strlcatf(compressor_name, len, " HD422");

        } else if(track->par->width == 1440) {

            av_strlcatf(compressor_name, len, " HD");

        } else

            av_strlcatf(compressor_name, len, " EX");



        av_strlcatf(compressor_name, len, " %d%c", track->par->height, interlaced ? 'i' : 'p');



        av_strlcatf(compressor_name, len, "%d", rate * (interlaced + 1));

    }

}

static int parse_audio_var(AVFormatContext *avctx, AVStream *st, const char *name, int size)

{

    AVIOContext *pb = avctx->pb;

    if (!strcmp(name, "__DIR_COUNT")) {

        st->nb_frames = var_read_int(pb, size);

    } else if (!strcmp(name, "AUDIO_FORMAT")) {

        st->codec->codec_id = var_read_int(pb, size);

    } else if (!strcmp(name, "COMPRESSION")) {

        st->codec->codec_tag = var_read_int(pb, size);

    } else if (!strcmp(name, "DEFAULT_VOL")) {

        var_read_metadata(avctx, name, size);

    } else if (!strcmp(name, "NUM_CHANNELS")) {

        st->codec->channels = var_read_int(pb, size);

        st->codec->channel_layout = (st->codec->channels == 1) ? AV_CH_LAYOUT_MONO : AV_CH_LAYOUT_STEREO;

    } else if (!strcmp(name, "SAMPLE_RATE")) {

        st->codec->sample_rate = var_read_int(pb, size);

        avpriv_set_pts_info(st, 33, 1, st->codec->sample_rate);

    } else if (!strcmp(name, "SAMPLE_WIDTH")) {

        st->codec->bits_per_coded_sample = var_read_int(pb, size) * 8;

    } else

        return -1;

    return 0;

}

int qemu_get_thread_id(void)

{

#if defined (__linux__)

    return syscall(SYS_gettid);

#else

    return getpid();

#endif

}

static int halfpel_interpol(SnowContext *s, uint8_t *halfpel[4][4], AVFrame *frame){

    int p,x,y;



    for(p=0; p < s->nb_planes; p++){

        int is_chroma= !!p;

        int w= is_chroma ? s->avctx->width >>s->chroma_h_shift : s->avctx->width;

        int h= is_chroma ? s->avctx->height>>s->chroma_v_shift : s->avctx->height;

        int ls= frame->linesize[p];

        uint8_t *src= frame->data[p];



        halfpel[1][p] = (uint8_t*) av_malloc_array(ls, (h + 2 * EDGE_WIDTH)) + EDGE_WIDTH * (1 + ls);

        halfpel[2][p] = (uint8_t*) av_malloc_array(ls, (h + 2 * EDGE_WIDTH)) + EDGE_WIDTH * (1 + ls);

        halfpel[3][p] = (uint8_t*) av_malloc_array(ls, (h + 2 * EDGE_WIDTH)) + EDGE_WIDTH * (1 + ls);

        if (!halfpel[1][p] || !halfpel[2][p] || !halfpel[3][p])

            return AVERROR(ENOMEM);



        halfpel[0][p]= src;

        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int i= y*ls + x;



                halfpel[1][p][i]= (20*(src[i] + src[i+1]) - 5*(src[i-1] + src[i+2]) + (src[i-2] + src[i+3]) + 16 )>>5;

            }

        }

        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int i= y*ls + x;



                halfpel[2][p][i]= (20*(src[i] + src[i+ls]) - 5*(src[i-ls] + src[i+2*ls]) + (src[i-2*ls] + src[i+3*ls]) + 16 )>>5;

            }

        }

        src= halfpel[1][p];

        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int i= y*ls + x;



                halfpel[3][p][i]= (20*(src[i] + src[i+ls]) - 5*(src[i-ls] + src[i+2*ls]) + (src[i-2*ls] + src[i+3*ls]) + 16 )>>5;

            }

        }



//FIXME border!

    }

    return 0;

}

static void yae_clear(ATempoContext *atempo)

{

    atempo->size = 0;

    atempo->head = 0;

    atempo->tail = 0;



    atempo->drift = 0;

    atempo->nfrag = 0;

    atempo->state = YAE_LOAD_FRAGMENT;



    atempo->position[0] = 0;

    atempo->position[1] = 0;



    atempo->frag[0].position[0] = 0;

    atempo->frag[0].position[1] = 0;

    atempo->frag[0].nsamples    = 0;



    atempo->frag[1].position[0] = 0;

    atempo->frag[1].position[1] = 0;

    atempo->frag[1].nsamples    = 0;



    // shift left position of 1st fragment by half a window

    // so that no re-normalization would be required for

    // the left half of the 1st fragment:

    atempo->frag[0].position[0] = -(int64_t)(atempo->window / 2);

    atempo->frag[0].position[1] = -(int64_t)(atempo->window / 2);



    av_frame_free(&atempo->dst_buffer);

    atempo->dst     = NULL;

    atempo->dst_end = NULL;



    atempo->request_fulfilled = 0;

    atempo->nsamples_in       = 0;

    atempo->nsamples_out      = 0;

}

int float32_is_nan( float32 a1 )

{

    float32u u;

    uint64_t a;

    u.f = a1;

    a = u.i;

    return ( 0xFF800000 < ( a<<1 ) );

}

void ff_put_pixels_clamped_c(const DCTELEM *block, uint8_t *restrict pixels,

                             int line_size)

{

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    /* read the pixels */

    for(i=0;i<8;i++) {

        pixels[0] = cm[block[0]];

        pixels[1] = cm[block[1]];

        pixels[2] = cm[block[2]];

        pixels[3] = cm[block[3]];

        pixels[4] = cm[block[4]];

        pixels[5] = cm[block[5]];

        pixels[6] = cm[block[6]];

        pixels[7] = cm[block[7]];



        pixels += line_size;

        block += 8;

    }

}

