static int opus_header(AVFormatContext *avf, int idx)

{

    struct ogg *ogg              = avf->priv_data;

    struct ogg_stream *os        = &ogg->streams[idx];

    AVStream *st                 = avf->streams[idx];

    struct oggopus_private *priv = os->private;

    uint8_t *packet              = os->buf + os->pstart;



    if (!priv) {

        priv = os->private = av_mallocz(sizeof(*priv));

        if (!priv)

            return AVERROR(ENOMEM);

    }



    if (os->flags & OGG_FLAG_BOS) {

        if (os->psize < OPUS_HEAD_SIZE || (AV_RL8(packet + 8) & 0xF0) != 0)

            return AVERROR_INVALIDDATA;

        st->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codecpar->codec_id   = AV_CODEC_ID_OPUS;

        st->codecpar->channels   = AV_RL8(packet + 9);



        priv->pre_skip        = AV_RL16(packet + 10);

        st->codecpar->initial_padding = priv->pre_skip;

        /*orig_sample_rate    = AV_RL32(packet + 12);*/

        /*gain                = AV_RL16(packet + 16);*/

        /*channel_map         = AV_RL8 (packet + 18);*/




        if (ff_alloc_extradata(st->codecpar, os->psize))

            return AVERROR(ENOMEM);



        memcpy(st->codecpar->extradata, packet, os->psize);



        st->codecpar->sample_rate = 48000;

        st->codecpar->seek_preroll = av_rescale(OPUS_SEEK_PREROLL_MS,

                                                st->codecpar->sample_rate, 1000);

        avpriv_set_pts_info(st, 64, 1, 48000);

        priv->need_comments = 1;

        return 1;

    }



    if (priv->need_comments) {

        if (os->psize < 8 || memcmp(packet, "OpusTags", 8))

            return AVERROR_INVALIDDATA;

        ff_vorbis_stream_comment(avf, st, packet + 8, os->psize - 8);

        priv->need_comments--;

        return 1;

    }



    return 0;

}

static int get_mmu_address(CPUState * env, target_ulong * physical,

			   int *prot, target_ulong address,

			   int rw, int access_type)

{

    int use_asid, is_code, n;

    tlb_t *matching = NULL;



    use_asid = (env->mmucr & MMUCR_SV) == 0 && (env->sr & SR_MD) == 0;

    is_code = env->pc == address;	/* Hack */



    /* Use a hack to find if this is an instruction or data access */

    if (env->pc == address && !(rw & PAGE_WRITE)) {

	n = find_itlb_entry(env, address, use_asid, 1);

	if (n >= 0) {

	    matching = &env->itlb[n];

	    if ((env->sr & SR_MD) & !(matching->pr & 2))

		n = MMU_ITLB_VIOLATION;

	    else

		*prot = PAGE_READ;

	}

    } else {

	n = find_utlb_entry(env, address, use_asid);

	if (n >= 0) {

	    matching = &env->utlb[n];

	    switch ((matching->pr << 1) | ((env->sr & SR_MD) ? 1 : 0)) {

	    case 0:		/* 000 */

	    case 2:		/* 010 */

		n = (rw & PAGE_WRITE) ? MMU_DTLB_VIOLATION_WRITE :

		    MMU_DTLB_VIOLATION_READ;

		break;

	    case 1:		/* 001 */

	    case 4:		/* 100 */

	    case 5:		/* 101 */

		if (rw & PAGE_WRITE)

		    n = MMU_DTLB_VIOLATION_WRITE;

		else

		    *prot = PAGE_READ;

		break;

	    case 3:		/* 011 */

	    case 6:		/* 110 */

	    case 7:		/* 111 */

		*prot = rw & (PAGE_READ | PAGE_WRITE);

		break;

	    }

	} else if (n == MMU_DTLB_MISS) {

	    n = (rw & PAGE_WRITE) ? MMU_DTLB_MISS_WRITE :

		MMU_DTLB_MISS_READ;

	}

    }

    if (n >= 0) {

	*physical = ((matching->ppn << 10) & ~(matching->size - 1)) |

	    (address & (matching->size - 1));

	if ((rw & PAGE_WRITE) & !matching->d)

	    n = MMU_DTLB_INITIAL_WRITE;

	else

	    n = MMU_OK;

    }

    return n;

}

