static int set_pix_fmt(AVCodecContext *avctx, vpx_codec_caps_t codec_caps,

                       struct vpx_codec_enc_cfg *enccfg, vpx_codec_flags_t *flags,

                       vpx_img_fmt_t *img_fmt)

{

    VPxContext av_unused *ctx = avctx->priv_data;

#ifdef VPX_IMG_FMT_HIGHBITDEPTH

    enccfg->g_bit_depth = enccfg->g_input_bit_depth = 8;

#endif

    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUVA420P:

        enccfg->g_profile = 0;

        *img_fmt = VPX_IMG_FMT_I420;

        return 0;

    case AV_PIX_FMT_YUV422P:

        enccfg->g_profile = 1;

        *img_fmt = VPX_IMG_FMT_I422;

        return 0;

#if VPX_IMAGE_ABI_VERSION >= 3

    case AV_PIX_FMT_YUV440P:

        enccfg->g_profile = 1;

        *img_fmt = VPX_IMG_FMT_I440;

        return 0;

    case AV_PIX_FMT_GBRP:

        ctx->vpx_cs = VPX_CS_SRGB;

#endif

    case AV_PIX_FMT_YUV444P:

        enccfg->g_profile = 1;

        *img_fmt = VPX_IMG_FMT_I444;

        return 0;

#ifdef VPX_IMG_FMT_HIGHBITDEPTH

    case AV_PIX_FMT_YUV420P10:

    case AV_PIX_FMT_YUV420P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV420P10 ? 10 : 12;

            enccfg->g_profile = 2;

            *img_fmt = VPX_IMG_FMT_I42016;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

    case AV_PIX_FMT_YUV422P10:

    case AV_PIX_FMT_YUV422P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV422P10 ? 10 : 12;

            enccfg->g_profile = 3;

            *img_fmt = VPX_IMG_FMT_I42216;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

#if VPX_IMAGE_ABI_VERSION >= 3

    case AV_PIX_FMT_YUV440P10:

    case AV_PIX_FMT_YUV440P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV440P10 ? 10 : 12;

            enccfg->g_profile = 3;

            *img_fmt = VPX_IMG_FMT_I44016;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

    case AV_PIX_FMT_GBRP10:

    case AV_PIX_FMT_GBRP12:

        ctx->vpx_cs = VPX_CS_SRGB;

#endif

    case AV_PIX_FMT_YUV444P10:

    case AV_PIX_FMT_YUV444P12:

        if (codec_caps & VPX_CODEC_CAP_HIGHBITDEPTH) {

            enccfg->g_bit_depth = enccfg->g_input_bit_depth =

                avctx->pix_fmt == AV_PIX_FMT_YUV444P10 ||

                avctx->pix_fmt == AV_PIX_FMT_GBRP10 ? 10 : 12;

            enccfg->g_profile = 3;

            *img_fmt = VPX_IMG_FMT_I44416;

            *flags |= VPX_CODEC_USE_HIGHBITDEPTH;

            return 0;

        }

        break;

#endif

    default:

        break;

    }

    av_log(avctx, AV_LOG_ERROR, "Unsupported pixel format.\n");

    return AVERROR_INVALIDDATA;

}

static int aasc_decode_frame(AVCodecContext *avctx,
                              void *data, int *data_size,
                              AVPacket *avpkt)
{
    const uint8_t *buf = avpkt->data;
    int buf_size = avpkt->size;
    AascContext *s = avctx->priv_data;
    int compr, i, stride, psize;
    s->frame.reference = 3;
    s->frame.buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE;
    if (avctx->reget_buffer(avctx, &s->frame)) {
        av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");
        return -1;
    compr = AV_RL32(buf);
    buf += 4;
    buf_size -= 4;
    psize = avctx->bits_per_coded_sample / 8;
    switch (avctx->codec_tag) {
    case MKTAG('A', 'A', 'S', '4'):
        bytestream2_init(&s->gb, buf - 4, buf_size + 4);
        ff_msrle_decode(avctx, (AVPicture*)&s->frame, 8, &s->gb);
        break;
    case MKTAG('A', 'A', 'S', 'C'):
    switch(compr){
    case 0:
        stride = (avctx->width * psize + psize) & ~psize;
        for(i = avctx->height - 1; i >= 0; i--){
            if(avctx->width * psize > buf_size){
                av_log(avctx, AV_LOG_ERROR, "Next line is beyond buffer bounds\n");
                break;
            memcpy(s->frame.data[0] + i*s->frame.linesize[0], buf, avctx->width * psize);
            buf += stride;
            buf_size -= stride;
        break;
    case 1:
        bytestream2_init(&s->gb, buf, buf_size);
        ff_msrle_decode(avctx, (AVPicture*)&s->frame, 8, &s->gb);
        break;
    default:
        av_log(avctx, AV_LOG_ERROR, "Unknown compression type %d\n", compr);
        return -1;
        break;
    default:
        av_log(avctx, AV_LOG_ERROR, "Unknown FourCC: %X\n", avctx->codec_tag);
        return -1;
    if (avctx->pix_fmt == AV_PIX_FMT_PAL8)
        memcpy(s->frame.data[1], s->palette, s->palette_size);
    *data_size = sizeof(AVFrame);
    *(AVFrame*)data = s->frame;
    /* report that the buffer was completely consumed */
    return buf_size;

int vncws_decode_frame(Buffer *input, uint8_t **payload,

                           size_t *payload_size, size_t *frame_size)

{

    unsigned char opcode = 0, fin = 0, has_mask = 0;

    size_t header_size = 0;

    uint32_t *payload32;

    WsHeader *header = (WsHeader *)input->buffer;

    WsMask mask;

    int i;



    if (input->offset < WS_HEAD_MIN_LEN + 4) {

        /* header not complete */

        return 0;

    }



    fin = (header->b0 & 0x80) >> 7;

    opcode = header->b0 & 0x0f;

    has_mask = (header->b1 & 0x80) >> 7;

    *payload_size = header->b1 & 0x7f;



    if (opcode == WS_OPCODE_CLOSE) {

        /* disconnect */

        return -1;

    }



    /* Websocket frame sanity check:

     * * Websocket fragmentation is not supported.

     * * All  websockets frames sent by a client have to be masked.

     * * Only binary encoding is supported.

     */

    if (!fin || !has_mask || opcode != WS_OPCODE_BINARY_FRAME) {

        VNC_DEBUG("Received faulty/unsupported Websocket frame\n");

        return -2;

    }



    if (*payload_size < 126) {

        header_size = 6;

        mask = header->u.m;

    } else if (*payload_size == 126 && input->offset >= 8) {

        *payload_size = be16_to_cpu(header->u.s16.l16);

        header_size = 8;

        mask = header->u.s16.m16;

    } else if (*payload_size == 127 && input->offset >= 14) {

        *payload_size = be64_to_cpu(header->u.s64.l64);

        header_size = 14;

        mask = header->u.s64.m64;

    } else {

        /* header not complete */

        return 0;

    }



    *frame_size = header_size + *payload_size;



    if (input->offset < *frame_size) {

        /* frame not complete */

        return 0;

    }



    *payload = input->buffer + header_size;



    /* unmask frame */

    /* process 1 frame (32 bit op) */

    payload32 = (uint32_t *)(*payload);

    for (i = 0; i < *payload_size / 4; i++) {

        payload32[i] ^= mask.u;

    }

    /* process the remaining bytes (if any) */

    for (i *= 4; i < *payload_size; i++) {

        (*payload)[i] ^= mask.c[i % 4];

    }



    return 1;

}

