static inline int parse_nal_units(AVCodecParserContext *s,

                                  AVCodecContext *avctx,

                                  const uint8_t *buf, int buf_size)

{

    H264Context *h = s->priv_data;

    const uint8_t *buf_end = buf + buf_size;

    unsigned int pps_id;

    unsigned int slice_type;

    int state;

    const uint8_t *ptr;



    /* set some sane default values */

    s->pict_type = FF_I_TYPE;

    s->key_frame = 0;



    h->s.avctx= avctx;

    h->sei_recovery_frame_cnt = -1;

    h->sei_dpb_output_delay         =  0;

    h->sei_cpb_removal_delay        = -1;

    h->sei_buffering_period_present =  0;



    for(;;) {

        int src_length, dst_length, consumed;

        buf = ff_find_start_code(buf, buf_end, &state);

        if(buf >= buf_end)

            break;

        --buf;

        src_length = buf_end - buf;

        switch (state & 0x1f) {

        case NAL_SLICE:

        case NAL_IDR_SLICE:

            // Do not walk the whole buffer just to decode slice header

            if (src_length > 20)

                src_length = 20;

            break;

        }

        ptr= ff_h264_decode_nal(h, buf, &dst_length, &consumed, src_length);

        if (ptr==NULL || dst_length < 0)

            break;



        init_get_bits(&h->s.gb, ptr, 8*dst_length);

        switch(h->nal_unit_type) {

        case NAL_SPS:

            ff_h264_decode_seq_parameter_set(h);

            break;

        case NAL_PPS:

            ff_h264_decode_picture_parameter_set(h, h->s.gb.size_in_bits);

            break;

        case NAL_SEI:

            ff_h264_decode_sei(h);

            break;

        case NAL_IDR_SLICE:

            s->key_frame = 1;

            /* fall through */

        case NAL_SLICE:

            get_ue_golomb(&h->s.gb);  // skip first_mb_in_slice

            slice_type = get_ue_golomb_31(&h->s.gb);

            s->pict_type = golomb_to_pict_type[slice_type % 5];

            if (h->sei_recovery_frame_cnt >= 0) {

                /* key frame, since recovery_frame_cnt is set */

                s->key_frame = 1;

            }

            pps_id= get_ue_golomb(&h->s.gb);

            if(pps_id>=MAX_PPS_COUNT) {

                av_log(h->s.avctx, AV_LOG_ERROR, "pps_id out of range\n");

                return -1;

            }

            if(!h->pps_buffers[pps_id]) {

                av_log(h->s.avctx, AV_LOG_ERROR, "non-existing PPS referenced\n");

                return -1;

            }

            h->pps= *h->pps_buffers[pps_id];

            if(!h->sps_buffers[h->pps.sps_id]) {

                av_log(h->s.avctx, AV_LOG_ERROR, "non-existing SPS referenced\n");

                return -1;

            }

            h->sps = *h->sps_buffers[h->pps.sps_id];

            h->frame_num = get_bits(&h->s.gb, h->sps.log2_max_frame_num);



            if(h->sps.frame_mbs_only_flag){

                h->s.picture_structure= PICT_FRAME;

            }else{

                if(get_bits1(&h->s.gb)) { //field_pic_flag

                    h->s.picture_structure= PICT_TOP_FIELD + get_bits1(&h->s.gb); //bottom_field_flag

                } else {

                    h->s.picture_structure= PICT_FRAME;

                }

            }



            if(h->sps.pic_struct_present_flag) {

                switch (h->sei_pic_struct) {

                    case SEI_PIC_STRUCT_TOP_FIELD:

                    case SEI_PIC_STRUCT_BOTTOM_FIELD:

                        s->repeat_pict = 0;

                        break;

                    case SEI_PIC_STRUCT_FRAME:

                    case SEI_PIC_STRUCT_TOP_BOTTOM:

                    case SEI_PIC_STRUCT_BOTTOM_TOP:

                        s->repeat_pict = 1;

                        break;

                    case SEI_PIC_STRUCT_TOP_BOTTOM_TOP:

                    case SEI_PIC_STRUCT_BOTTOM_TOP_BOTTOM:

                        s->repeat_pict = 2;

                        break;

                    case SEI_PIC_STRUCT_FRAME_DOUBLING:

                        s->repeat_pict = 3;

                        break;

                    case SEI_PIC_STRUCT_FRAME_TRIPLING:

                        s->repeat_pict = 5;

                        break;

                    default:

                        s->repeat_pict = h->s.picture_structure == PICT_FRAME ? 1 : 0;

                        break;

                }

            } else {

                s->repeat_pict = h->s.picture_structure == PICT_FRAME ? 1 : 0;

            }



            return 0; /* no need to evaluate the rest */

        }

        buf += consumed;

    }

    /* didn't find a picture! */

    av_log(h->s.avctx, AV_LOG_ERROR, "missing picture in access unit\n");

    return -1;

}

int avpriv_dv_produce_packet(DVDemuxContext *c, AVPacket *pkt,

                      uint8_t* buf, int buf_size, int64_t pos)

{

    int size, i;

    uint8_t *ppcm[4] = {0};



    if (buf_size < DV_PROFILE_BYTES ||

        !(c->sys = avpriv_dv_frame_profile(c->sys, buf, buf_size)) ||

        buf_size < c->sys->frame_size) {

          return -1;   /* Broken frame, or not enough data */

    }



    /* Queueing audio packet */

    /* FIXME: in case of no audio/bad audio we have to do something */

    size = dv_extract_audio_info(c, buf);

    for (i = 0; i < c->ach; i++) {

       c->audio_pkt[i].pos  = pos;

       c->audio_pkt[i].size = size;

       c->audio_pkt[i].pts  = c->abytes * 30000*8 / c->ast[i]->codec->bit_rate;

       ppcm[i] = c->audio_buf[i];

    }

    dv_extract_audio(buf, ppcm, c->sys);



    /* We work with 720p frames split in half, thus even frames have

     * channels 0,1 and odd 2,3. */

    if (c->sys->height == 720) {

        if (buf[1] & 0x0C) {

            c->audio_pkt[2].size = c->audio_pkt[3].size = 0;

        } else {

            c->audio_pkt[0].size = c->audio_pkt[1].size = 0;

            c->abytes += size;

        }

    } else {

        c->abytes += size;

    }



    /* Now it's time to return video packet */

    size = dv_extract_video_info(c, buf);

    av_init_packet(pkt);

    pkt->data         = buf;

    pkt->pos          = pos;

    pkt->size         = size;

    pkt->flags       |= AV_PKT_FLAG_KEY;

    pkt->stream_index = c->vst->id;

    pkt->pts          = c->frames;



    c->frames++;



    return size;

}

static int cd_read_sector(IDEState *s, int lba, uint8_t *buf, int sector_size)

{

    int ret;



    switch(sector_size) {

    case 2048:

        block_acct_start(blk_get_stats(s->blk), &s->acct,

                         4 * BDRV_SECTOR_SIZE, BLOCK_ACCT_READ);

        ret = blk_read(s->blk, (int64_t)lba << 2, buf, 4);

        block_acct_done(blk_get_stats(s->blk), &s->acct);

        break;

    case 2352:

        block_acct_start(blk_get_stats(s->blk), &s->acct,

                         4 * BDRV_SECTOR_SIZE, BLOCK_ACCT_READ);

        ret = blk_read(s->blk, (int64_t)lba << 2, buf + 16, 4);

        block_acct_done(blk_get_stats(s->blk), &s->acct);

        if (ret < 0)

            return ret;

        cd_data_to_raw(buf, lba);

        break;

    default:

        ret = -EIO;

        break;

    }

    return ret;

}

int qemu_timeout_ns_to_ms(int64_t ns)

{

    int64_t ms;

    if (ns < 0) {

        return -1;

    }



    if (!ns) {

        return 0;

    }



    /* Always round up, because it's better to wait too long than to wait too

     * little and effectively busy-wait

     */

    ms = DIV_ROUND_UP(ns, SCALE_MS);



    /* To avoid overflow problems, limit this to 2^31, i.e. approx 25 days */

    if (ms > (int64_t) INT32_MAX) {

        ms = INT32_MAX;

    }



    return (int) ms;

}

bool aio_poll(AioContext *ctx, bool blocking)

{

    AioHandler *node;

    int i, ret;

    bool progress;

    int64_t timeout;



    aio_context_acquire(ctx);

    progress = false;



    /* aio_notify can avoid the expensive event_notifier_set if

     * everything (file descriptors, bottom halves, timers) will

     * be re-evaluated before the next blocking poll().  This is

     * already true when aio_poll is called with blocking == false;

     * if blocking == true, it is only true after poll() returns,

     * so disable the optimization now.

     */

    if (blocking) {

        atomic_add(&ctx->notify_me, 2);

    }



    ctx->walking_handlers++;



    assert(npfd == 0);



    /* fill pollfds */



    if (!aio_epoll_enabled(ctx)) {

        QLIST_FOREACH(node, &ctx->aio_handlers, node) {

            if (!node->deleted && node->pfd.events

                && aio_node_check(ctx, node->is_external)) {

                add_pollfd(node);

            }

        }

    }



    timeout = blocking ? aio_compute_timeout(ctx) : 0;



    /* wait until next event */

    if (timeout) {

        aio_context_release(ctx);

    }

    if (aio_epoll_check_poll(ctx, pollfds, npfd, timeout)) {

        AioHandler epoll_handler;



        epoll_handler.pfd.fd = ctx->epollfd;

        epoll_handler.pfd.events = G_IO_IN | G_IO_OUT | G_IO_HUP | G_IO_ERR;

        npfd = 0;

        add_pollfd(&epoll_handler);

        ret = aio_epoll(ctx, pollfds, npfd, timeout);

    } else  {

        ret = qemu_poll_ns(pollfds, npfd, timeout);

    }

    if (blocking) {

        atomic_sub(&ctx->notify_me, 2);

    }

    if (timeout) {

        aio_context_acquire(ctx);

    }



    aio_notify_accept(ctx);



    /* if we have any readable fds, dispatch event */

    if (ret > 0) {

        for (i = 0; i < npfd; i++) {

            nodes[i]->pfd.revents = pollfds[i].revents;

        }

    }



    npfd = 0;

    ctx->walking_handlers--;



    /* Run dispatch even if there were no readable fds to run timers */

    if (aio_dispatch(ctx, ret > 0)) {

        progress = true;

    }



    aio_context_release(ctx);



    return progress;

}

