        obj = qobject_from_json(qstring_get_str(str));

        g_assert(obj != NULL);

        g_assert(qobject_type(obj) == QTYPE_QDICT);



        g_assert(compare_litqobj_to_qobj(&test_cases[i].decoded, obj) == 1);

        qobject_decref(obj);

        QDECREF(str);

    }

}

