static void ehci_execute_complete(EHCIQueue *q)

{

    EHCIPacket *p = QTAILQ_FIRST(&q->packets);



    assert(p != NULL);

    assert(p->qtdaddr == q->qtdaddr);

    assert(p->async != EHCI_ASYNC_INFLIGHT);

    p->async = EHCI_ASYNC_NONE;



    DPRINTF("execute_complete: qhaddr 0x%x, next %x, qtdaddr 0x%x, status %d\n",

            q->qhaddr, q->qh.next, q->qtdaddr, q->usb_status);



    if (p->usb_status < 0) {

        switch (p->usb_status) {

        case USB_RET_IOERROR:

        case USB_RET_NODEV:

            q->qh.token |= (QTD_TOKEN_HALT | QTD_TOKEN_XACTERR);

            set_field(&q->qh.token, 0, QTD_TOKEN_CERR);

            ehci_record_interrupt(q->ehci, USBSTS_ERRINT);

            break;

        case USB_RET_STALL:

            q->qh.token |= QTD_TOKEN_HALT;

            ehci_record_interrupt(q->ehci, USBSTS_ERRINT);

            break;

        case USB_RET_NAK:

            set_field(&q->qh.altnext_qtd, 0, QH_ALTNEXT_NAKCNT);

            return; /* We're not done yet with this transaction */

        case USB_RET_BABBLE:

            q->qh.token |= (QTD_TOKEN_HALT | QTD_TOKEN_BABBLE);

            ehci_record_interrupt(q->ehci, USBSTS_ERRINT);

            break;

        default:

            /* should not be triggerable */

            fprintf(stderr, "USB invalid response %d\n", p->usb_status);

            assert(0);

            break;

        }

    } else if ((p->usb_status > p->tbytes) && (p->pid == USB_TOKEN_IN)) {

        p->usb_status = USB_RET_BABBLE;

        q->qh.token |= (QTD_TOKEN_HALT | QTD_TOKEN_BABBLE);

        ehci_record_interrupt(q->ehci, USBSTS_ERRINT);

    } else {

        // TODO check 4.12 for splits



        if (p->tbytes && p->pid == USB_TOKEN_IN) {

            p->tbytes -= p->usb_status;

        } else {

            p->tbytes = 0;

        }



        DPRINTF("updating tbytes to %d\n", p->tbytes);

        set_field(&q->qh.token, p->tbytes, QTD_TOKEN_TBYTES);

    }

    ehci_finish_transfer(q, p->usb_status);

    qemu_sglist_destroy(&p->sgl);

    usb_packet_unmap(&p->packet);



    q->qh.token ^= QTD_TOKEN_DTOGGLE;

    q->qh.token &= ~QTD_TOKEN_ACTIVE;



    if (q->qh.token & QTD_TOKEN_IOC) {

        ehci_record_interrupt(q->ehci, USBSTS_INT);

    }

}

static bool vring_notify(VirtIODevice *vdev, VirtQueue *vq)

{

    uint16_t old, new;

    bool v;



    /* Always notify when queue is empty (when feature acknowledge) */

    if (((vdev->guest_features & (1 << VIRTIO_F_NOTIFY_ON_EMPTY)) &&

         !vq->inuse && vring_avail_idx(vq) == vq->last_avail_idx)) {

        return true;

    }



    if (!(vdev->guest_features & (1 << VIRTIO_RING_F_EVENT_IDX))) {

        return !(vring_avail_flags(vq) & VRING_AVAIL_F_NO_INTERRUPT);

    }



    v = vq->signalled_used_valid;

    vq->signalled_used_valid = true;

    old = vq->signalled_used;

    new = vq->signalled_used = vring_used_idx(vq);

    return !v || vring_need_event(vring_used_event(vq), new, old);

}

static av_always_inline int normal_limit(uint8_t *p, ptrdiff_t stride, int E, int I)

{

    LOAD_PIXELS

    return simple_limit(p, stride, E)

        && FFABS(p3-p2) <= I && FFABS(p2-p1) <= I && FFABS(p1-p0) <= I

        && FFABS(q3-q2) <= I && FFABS(q2-q1) <= I && FFABS(q1-q0) <= I;

}

static void qdev_prop_set_globals_for_type(DeviceState *dev,

                                           const char *typename)

{

    GList *l;



    for (l = global_props; l; l = l->next) {

        GlobalProperty *prop = l->data;

        Error *err = NULL;



        if (strcmp(typename, prop->driver) != 0) {

            continue;

        }

        prop->used = true;

        object_property_parse(OBJECT(dev), prop->value, prop->property, &err);

        if (err != NULL) {

            error_prepend(&err, "can't apply global %s.%s=%s: ",

                          prop->driver, prop->property, prop->value);

            if (!dev->hotplugged && prop->errp) {

                error_propagate(prop->errp, err);

            } else {

                assert(prop->user_provided);

                warn_report_err(err);

            }

        }

    }

}

static inline unsigned int get_seg_limit(uint32_t e1, uint32_t e2)

{

    unsigned int limit;

    limit = (e1 & 0xffff) | (e2 & 0x000f0000);

    if (e2 & DESC_G_MASK)

        limit = (limit << 12) | 0xfff;

    return limit;

}

