static void gd_update(DisplayChangeListener *dcl,

                      DisplayState *ds, int x, int y, int w, int h)

{

    GtkDisplayState *s = ds->opaque;

    int x1, x2, y1, y2;

    int mx, my;

    int fbw, fbh;

    int ww, wh;



    DPRINTF("update(x=%d, y=%d, w=%d, h=%d)\n", x, y, w, h);



    x1 = floor(x * s->scale_x);

    y1 = floor(y * s->scale_y);



    x2 = ceil(x * s->scale_x + w * s->scale_x);

    y2 = ceil(y * s->scale_y + h * s->scale_y);



    fbw = ds_get_width(s->ds) * s->scale_x;

    fbh = ds_get_height(s->ds) * s->scale_y;



    gdk_drawable_get_size(gtk_widget_get_window(s->drawing_area), &ww, &wh);



    mx = my = 0;

    if (ww > fbw) {

        mx = (ww - fbw) / 2;

    }

    if (wh > fbh) {

        my = (wh - fbh) / 2;

    }



    gtk_widget_queue_draw_area(s->drawing_area, mx + x1, my + y1, (x2 - x1), (y2 - y1));

}

static int read_uncompressed_sgi(unsigned char* out_buf, SgiState *s)

{

    int x, y, z;

    unsigned int offset = s->height * s->width * s->bytes_per_channel;

    GetByteContext gp[4];

    uint8_t *out_end;



    /* Test buffer size. */

    if (offset * s->depth > bytestream2_get_bytes_left(&s->g))

        return AVERROR_INVALIDDATA;



    /* Create a reader for each plane */

    for (z = 0; z < s->depth; z++) {

        gp[z] = s->g;

        bytestream2_skip(&gp[z], z * offset);

    }



    for (y = s->height - 1; y >= 0; y--) {

        out_end = out_buf + (y * s->linesize);

        if (s->bytes_per_channel == 1) {

            for (x = s->width; x > 0; x--) {

                bytestream2_get_bufferu(&gp[z], out_end, s->depth);

                out_end += s->depth;

            }

        } else {

            uint16_t *out16 = (uint16_t *)out_end;

            for (x = s->width; x > 0; x--)

                for (z = 0; z < s->depth; z++)

                    *out16++ = bytestream2_get_ne16u(&gp[z]);

        }

    }

    return 0;

}

