static int dv_extract_audio(uint8_t *frame, uint8_t *ppcm[4],

                            const DVprofile *sys)

{

    int size, chan, i, j, d, of, smpls, freq, quant, half_ch;

    uint16_t lc, rc;

    const uint8_t *as_pack;

    uint8_t *pcm, ipcm;



    as_pack = dv_extract_pack(frame, dv_audio_source);

    if (!as_pack)    /* No audio ? */

        return 0;



    smpls = as_pack[1]      & 0x3f; /* samples in this frame - min. samples */

    freq  = as_pack[4] >> 3 & 0x07; /* 0 - 48kHz, 1 - 44,1kHz, 2 - 32kHz */

    quant = as_pack[4]      & 0x07; /* 0 - 16bit linear, 1 - 12bit nonlinear */



    if (quant > 1)

        return -1;  /* unsupported quantization */



    if (freq >= FF_ARRAY_ELEMS(dv_audio_frequency))

        return AVERROR_INVALIDDATA;



    size    = (sys->audio_min_samples[freq] + smpls) * 4; /* 2ch, 2bytes */

    half_ch = sys->difseg_size / 2;



    /* We work with 720p frames split in half, thus even frames have

     * channels 0,1 and odd 2,3. */

    ipcm = (sys->height == 720 && !(frame[1] & 0x0C)) ? 2 : 0;



    /* for each DIF channel */

    for (chan = 0; chan < sys->n_difchan; chan++) {

        /* next stereo channel (50Mbps and 100Mbps only) */

        pcm = ppcm[ipcm++];

        if (!pcm)

            break;



        /* for each DIF segment */

        for (i = 0; i < sys->difseg_size; i++) {

            frame += 6 * 80; /* skip DIF segment header */

            if (quant == 1 && i == half_ch) {

                /* next stereo channel (12bit mode only) */

                pcm = ppcm[ipcm++];

                if (!pcm)

                    break;

            }



            /* for each AV sequence */

            for (j = 0; j < 9; j++) {

                for (d = 8; d < 80; d += 2) {

                    if (quant == 0) {  /* 16bit quantization */

                        of = sys->audio_shuffle[i][j] +

                             (d - 8) / 2 * sys->audio_stride;

                        if (of * 2 >= size)

                            continue;



                        /* FIXME: maybe we have to admit that DV is a

                         * big-endian PCM */

                        pcm[of * 2]     = frame[d + 1];

                        pcm[of * 2 + 1] = frame[d];



                        if (pcm[of * 2 + 1] == 0x80 && pcm[of * 2] == 0x00)

                            pcm[of * 2 + 1] = 0;

                    } else {           /* 12bit quantization */

                        lc = ((uint16_t)frame[d]     << 4) |

                             ((uint16_t)frame[d + 2] >> 4);

                        rc = ((uint16_t)frame[d + 1] << 4) |

                             ((uint16_t)frame[d + 2] & 0x0f);

                        lc = (lc == 0x800 ? 0 : dv_audio_12to16(lc));

                        rc = (rc == 0x800 ? 0 : dv_audio_12to16(rc));



                        of = sys->audio_shuffle[i % half_ch][j] +

                             (d - 8) / 3 * sys->audio_stride;

                        if (of * 2 >= size)

                            continue;



                        /* FIXME: maybe we have to admit that DV is a

                         * big-endian PCM */

                        pcm[of * 2]     = lc & 0xff;

                        pcm[of * 2 + 1] = lc >> 8;

                        of = sys->audio_shuffle[i % half_ch + half_ch][j] +

                             (d - 8) / 3 * sys->audio_stride;

                        /* FIXME: maybe we have to admit that DV is a

                         * big-endian PCM */

                        pcm[of * 2]     = rc & 0xff;

                        pcm[of * 2 + 1] = rc >> 8;

                        ++d;

                    }

                }



                frame += 16 * 80; /* 15 Video DIFs + 1 Audio DIF */

            }

        }

    }



    return size;

}

static void sunmouse_event(void *opaque,

                               int dx, int dy, int dz, int buttons_state)

{

    ChannelState *s = opaque;

    int ch;



    MS_DPRINTF("dx=%d dy=%d buttons=%01x\n", dx, dy, buttons_state);



    ch = 0x80 | 0x7; /* protocol start byte, no buttons pressed */



    if (buttons_state & MOUSE_EVENT_LBUTTON)

        ch ^= 0x4;

    if (buttons_state & MOUSE_EVENT_MBUTTON)

        ch ^= 0x2;

    if (buttons_state & MOUSE_EVENT_RBUTTON)

        ch ^= 0x1;



    put_queue(s, ch);



    ch = dx;



    if (ch > 127)

        ch=127;

    else if (ch < -127)

        ch=-127;



    put_queue(s, ch & 0xff);



    ch = -dy;



    if (ch > 127)

        ch=127;

    else if (ch < -127)

        ch=-127;



    put_queue(s, ch & 0xff);



    // MSC protocol specify two extra motion bytes



    put_queue(s, 0);

    put_queue(s, 0);

}

void ff_MPV_encode_init_x86(MpegEncContext *s)

{

    int mm_flags = av_get_cpu_flags();

    const int dct_algo = s->avctx->dct_algo;



    if (dct_algo == FF_DCT_AUTO || dct_algo == FF_DCT_MMX) {

#if HAVE_MMX_INLINE

        if (mm_flags & AV_CPU_FLAG_MMX && HAVE_MMX)

            s->dct_quantize = dct_quantize_MMX;

#endif

#if HAVE_MMXEXT_INLINE

        if (mm_flags & AV_CPU_FLAG_MMXEXT && HAVE_MMXEXT)

            s->dct_quantize = dct_quantize_MMX2;

#endif

#if HAVE_SSE2_INLINE

        if (mm_flags & AV_CPU_FLAG_SSE2 && HAVE_SSE2)

            s->dct_quantize = dct_quantize_SSE2;

#endif

#if HAVE_SSSE3_INLINE

        if (mm_flags & AV_CPU_FLAG_SSSE3)

            s->dct_quantize = dct_quantize_SSSE3;

#endif

    }

}

static inline void gen_op_multiply(TCGv dst, TCGv src1, TCGv src2, int sign_ext)

{

    TCGv_i32 r_src1, r_src2;

    TCGv_i64 r_temp, r_temp2;



    r_src1 = tcg_temp_new_i32();

    r_src2 = tcg_temp_new_i32();



    tcg_gen_trunc_tl_i32(r_src1, src1);

    tcg_gen_trunc_tl_i32(r_src2, src2);



    r_temp = tcg_temp_new_i64();

    r_temp2 = tcg_temp_new_i64();



    if (sign_ext) {

        tcg_gen_ext_i32_i64(r_temp, r_src2);

        tcg_gen_ext_i32_i64(r_temp2, r_src1);

    } else {

        tcg_gen_extu_i32_i64(r_temp, r_src2);

        tcg_gen_extu_i32_i64(r_temp2, r_src1);

    }



    tcg_gen_mul_i64(r_temp2, r_temp, r_temp2);



    tcg_gen_shri_i64(r_temp, r_temp2, 32);

    tcg_gen_trunc_i64_tl(cpu_tmp0, r_temp);

    tcg_temp_free_i64(r_temp);

    tcg_gen_andi_tl(cpu_y, cpu_tmp0, 0xffffffff);



    tcg_gen_trunc_i64_tl(dst, r_temp2);



    tcg_temp_free_i64(r_temp2);



    tcg_temp_free_i32(r_src1);

    tcg_temp_free_i32(r_src2);

}

static void decode_opc(DisasContext * ctx)

{

    uint32_t old_flags = ctx->envflags;



    _decode_opc(ctx);



    if (old_flags & DELAY_SLOT_MASK) {

        /* go out of the delay slot */

        ctx->envflags &= ~DELAY_SLOT_MASK;

        tcg_gen_movi_i32(cpu_flags, ctx->envflags);

        ctx->bstate = BS_BRANCH;

        if (old_flags & DELAY_SLOT_CONDITIONAL) {

	    gen_delayed_conditional_jump(ctx);

        } else if (old_flags & DELAY_SLOT) {

            gen_jump(ctx);

	}



    }

}

int qcow2_pre_write_overlap_check(BlockDriverState *bs, int chk, int64_t offset,

                                  int64_t size)

{

    int ret = qcow2_check_metadata_overlap(bs, chk, offset, size);



    if (ret < 0) {

        return ret;

    } else if (ret > 0) {

        int metadata_ol_bitnr = ffs(ret) - 1;

        char *message;

        QObject *data;



        assert(metadata_ol_bitnr < QCOW2_OL_MAX_BITNR);



        fprintf(stderr, "qcow2: Preventing invalid write on metadata (overlaps "

                "with %s); image marked as corrupt.\n",

                metadata_ol_names[metadata_ol_bitnr]);

        message = g_strdup_printf("Prevented %s overwrite",

                metadata_ol_names[metadata_ol_bitnr]);

        data = qobject_from_jsonf("{ 'device': %s, 'msg': %s, 'offset': %"

                PRId64 ", 'size': %" PRId64 " }", bs->device_name, message,

                offset, size);

        monitor_protocol_event(QEVENT_BLOCK_IMAGE_CORRUPTED, data);

        g_free(message);

        qobject_decref(data);



        qcow2_mark_corrupt(bs);

        bs->drv = NULL; /* make BDS unusable */

        return -EIO;

    }



    return 0;

}

